# -*- coding: utf-8 -*-
"""365 versiculos biblicos - um para cada dia do ano (pt/en/es).
Cada entrada: (referencia_pt, texto_pt, referencia_en, texto_en, referencia_es, texto_es).
Somente caracteres Latin-1/WinAnsi sao usados para renderizacao segura no PDF.
"""


_VERSE_TABLE = [
    ('Salmo 23:1', 'O Senhor é o meu pastor; nada me faltará.', 'Psalm 23:1', 'The Lord is my shepherd; I shall not want.', 'Salmo 23:1', 'El Señor es mi pastor; nada me faltará.'),
    ('Salmo 118:24', 'Este é o dia que fez o Senhor; regozijemo-nos e alegremo-nos nele.', 'Psalm 118:24', 'This is the day the Lord has made; let us rejoice and be glad in it.', 'Salmo 118:24', 'Este es el día que hizo el Señor; nos gozaremos y alegraremos en él.'),
    ('Salmo 46:1', 'Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia.', 'Psalm 46:1', 'God is our refuge and strength, an ever-present help in trouble.', 'Salmo 46:1', 'Dios es nuestro refugio y fortaleza, nuestro pronto auxilio en las tribulaciones.'),
    ('Provérbios 3:5', 'Confia no Senhor de todo o teu coração e não te estribes no teu próprio entendimento.', 'Proverbs 3:5', 'Trust in the Lord with all your heart and lean not on your own understanding.', 'Proverbios 3:5', 'Confía en el Señor con todo tu corazón, y no te apoyes en tu propia prudencia.'),
    ('Salmo 37:5', 'Entrega o teu caminho ao Senhor; confia nele, e ele tudo fará.', 'Psalm 37:5', 'Commit your way to the Lord; trust in him and he will do this.', 'Salmo 37:5', 'Encomienda al Señor tu camino, y confía en él; y él hará.'),
    ('Isaías 41:10', 'Não temas, porque eu sou contigo; não te assombres, porque eu sou o teu Deus.', 'Isaiah 41:10', 'Fear not, for I am with you; be not dismayed, for I am your God.', 'Isaías 41:10', 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios.'),
    ('Salmo 91:2', 'Direi do Senhor: Ele é o meu Deus, o meu refúgio e a minha fortaleza.', 'Psalm 91:2', 'I will say of the Lord: He is my God, in whom I trust.', 'Salmo 91:2', 'Diré yo del Señor: Él es mi Dios, mi refugio y mi fortaleza.'),
    ('Mateus 6:33', 'Buscai primeiro o reino de Deus e a sua justiça, e todas as coisas vos serão acrescentadas.', 'Matthew 6:33', 'Seek first the kingdom of God and his righteousness, and all these things will be added to you.', 'Mateo 6:33', 'Buscad primero el reino de Dios y su justicia, y todas estas cosas os serán añadidas.'),
    ('Salmo 28:7', 'O Senhor é a minha força e o meu escudo; nele confiou o meu coração.', 'Psalm 28:7', 'The Lord is my strength and my shield; my heart trusts in him.', 'Salmo 28:7', 'El Señor es mi fortaleza y mi escudo; en él confió mi corazón.'),
    ('Filipenses 4:13', 'Tudo posso naquele que me fortalece.', 'Philippians 4:13', 'I can do all things through him who strengthens me.', 'Filipenses 4:13', 'Todo lo puedo en Cristo que me fortalece.'),
    ('Salmo 55:22', 'Lança o teu cuidado sobre o Senhor, e ele te susterá.', 'Psalm 55:22', 'Cast your cares on the Lord and he will sustain you.', 'Salmo 55:22', 'Echa sobre el Señor tu carga, y él te sustentará.'),
    ('Jeremias 29:11', 'Porque eu sei os planos que tenho para vós, planos de paz e não de mal.', 'Jeremiah 29:11', 'For I know the plans I have for you, plans to give you hope and a future.', 'Jeremías 29:11', 'Porque yo sé los pensamientos que tengo acerca de vosotros, pensamientos de paz y no de mal.'),
    ('Salmo 34:8', 'Provai e vede que o Senhor é bom; bem-aventurado o homem que nele confia.', 'Psalm 34:8', 'Taste and see that the Lord is good; blessed is the one who takes refuge in him.', 'Salmo 34:8', 'Gustad y ved que es bueno el Señor; dichoso el hombre que confía en él.'),
    ('João 14:27', 'Deixo-vos a paz, a minha paz vos dou; não se turbe o vosso coração.', 'John 14:27', 'Peace I leave with you; my peace I give you. Do not let your hearts be troubled.', 'Juan 14:27', 'La paz os dejo, mi paz os doy; no se turbe vuestro corazón.'),
    ('Salmo 121:1', 'Elevo os meus olhos para os montes; de onde me virá o socorro?', 'Psalm 121:1', 'I lift up my eyes to the mountains; where does my help come from?', 'Salmo 121:1', 'Alzaré mis ojos a los montes; ¿de dónde vendrá mi socorro?'),
    ('Salmo 121:2', 'O meu socorro vem do Senhor, que fez o céu e a terra.', 'Psalm 121:2', 'My help comes from the Lord, the Maker of heaven and earth.', 'Salmo 121:2', 'Mi socorro viene del Señor, que hizo los cielos y la tierra.'),
    ('Romanos 8:28', 'Todas as coisas cooperam para o bem daqueles que amam a Deus.', 'Romans 8:28', 'In all things God works for the good of those who love him.', 'Romanos 8:28', 'Todas las cosas ayudan a bien, a los que aman a Dios.'),
    ('Salmo 143:8', 'Faze-me ouvir pela manhã a tua benignidade, pois em ti confio.', 'Psalm 143:8', 'Let the morning bring me word of your unfailing love, for I have put my trust in you.', 'Salmo 143:8', 'Hazme oír por la mañana tu misericordia, porque en ti he confiado.'),
    ('Provérbios 16:3', 'Confia ao Senhor as tuas obras, e os teus pensamentos serão estabelecidos.', 'Proverbs 16:3', 'Commit to the Lord whatever you do, and he will establish your plans.', 'Proverbios 16:3', 'Encomienda al Señor tus obras, y tus pensamientos serán afirmados.'),
    ('Salmo 62:1', 'A minha alma espera somente em Deus; dele vem a minha salvação.', 'Psalm 62:1', 'Truly my soul finds rest in God; my salvation comes from him.', 'Salmo 62:1', 'En Dios solamente está acallada mi alma; de él viene mi salvación.'),
    ('Mateus 11:28', 'Vinde a mim, todos os que estais cansados e oprimidos, e eu vos aliviarei.', 'Matthew 11:28', 'Come to me, all you who are weary and burdened, and I will give you rest.', 'Mateo 11:28', 'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar.'),
    ('Salmo 5:3', 'Pela manhã ouvirás a minha voz, ó Senhor; pela manhã apresentarei a ti a minha oração.', 'Psalm 5:3', 'In the morning, Lord, you hear my voice; in the morning I lay my requests before you.', 'Salmo 5:3', 'Oye mi voz de mañana, oh Señor; de mañana me presentaré delante de ti y esperaré.'),
    ('Josué 1:9', 'Sê forte e corajoso; não temas, porque o Senhor teu Deus está contigo por onde quer que andares.', 'Joshua 1:9', 'Be strong and courageous; do not be afraid, for the Lord your God will be with you wherever you go.', 'Josué 1:9', 'Esfuérzate y sé valiente; no temas, porque el Señor tu Dios estará contigo dondequiera que vayas.'),
    ('Salmo 73:26', 'A minha carne e o meu coração desfalecem; mas Deus é a força do meu coração.', 'Psalm 73:26', 'My flesh and my heart may fail, but God is the strength of my heart.', 'Salmo 73:26', 'Mi carne y mi corazón desfallecen; mas la roca de mi corazón y mi porción es Dios para siempre.'),
    ('Romanos 15:13', 'O Deus de esperança vos encha de todo o gozo e paz em crença.', 'Romans 15:13', 'May the God of hope fill you with all joy and peace as you trust in him.', 'Romanos 15:13', 'El Dios de esperanza os llene de todo gozo y paz en el creer.'),
    ('Salmo 34:4', 'Busquei ao Senhor, e ele me respondeu; livrou-me de todos os meus temores.', 'Psalm 34:4', 'I sought the Lord, and he answered me; he delivered me from all my fears.', 'Salmo 34:4', 'Busqué al Señor, y él me oyó, y me libró de todos mis temores.'),
    ('Mateus 7:7', 'Pedi, e dar-se-vos-á; buscai, e encontrareis; batei, e abrir-se-vos-á.', 'Matthew 7:7', 'Ask and it will be given to you; seek and you will find; knock and the door will be opened to you.', 'Mateo 7:7', 'Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá.'),
    ('Salmo 139:14', 'Eu te louvarei, porque de um modo terrível e tão maravilhoso fui formado.', 'Psalm 139:14', 'I praise you because I am fearfully and wonderfully made.', 'Salmo 139:14', 'Te alabaré, porque formidables, maravillosas son tus obras.'),
    ('Isaías 40:31', 'Os que esperam no Senhor renovarão as suas forças; subirão com asas como águias.', 'Isaiah 40:31', 'Those who hope in the Lord will renew their strength; they will soar on wings like eagles.', 'Isaías 40:31', 'Los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas.'),
    ('Salmo 25:5', 'Guia-me na tua verdade e ensina-me, pois tu és o Deus da minha salvação.', 'Psalm 25:5', 'Guide me in your truth and teach me, for you are God my Savior.', 'Salmo 25:5', 'Encamíname en tu verdad, y enséñame, porque tú eres el Dios de mi salvación.'),
    ('Filipenses 4:6', 'Não estejais ansiosos por coisa alguma; em tudo apresentai os vossos pedidos a Deus.', 'Philippians 4:6', 'Do not be anxious about anything, but present your requests to God.', 'Filipenses 4:6', 'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios.'),
    ('Salmo 32:8', 'Instruir-te-ei e ensinar-te-ei o caminho que deves seguir; aconselhar-te-ei.', 'Psalm 32:8', 'I will instruct you and teach you in the way you should go; I will counsel you.', 'Salmo 32:8', 'Te haré entender, y te enseñaré el camino en que debes andar; sobre ti fijaré mis ojos.'),
    ('2 Coríntios 5:7', 'Porque andamos por fé, e não por vista.', '2 Corinthians 5:7', 'For we live by faith, not by sight.', '2 Corintios 5:7', 'Porque por fe andamos, no por vista.'),
    ('Salmo 18:2', 'O Senhor é a minha rocha, a minha fortaleza e o meu libertador.', 'Psalm 18:2', 'The Lord is my rock, my fortress and my deliverer.', 'Salmo 18:2', 'El Señor es mi roca, mi fortaleza y mi libertador.'),
    ('Lamentações 3:23', 'As misericórdias do Senhor se renovam cada manhã; grande é a tua fidelidade.', 'Lamentations 3:23', 'His mercies are new every morning; great is your faithfulness.', 'Lamentaciones 3:23', 'Nuevas son cada mañana; grande es tu fidelidad.'),
    ('Salmo 144:15', 'Bem-aventurado o povo cujo Deus é o Senhor.', 'Psalm 144:15', 'Blessed is the people whose God is the Lord.', 'Salmo 144:15', 'Bienaventurado el pueblo cuyo Dios es el Señor.'),
    ('1 Coríntios 13:13', 'Agora permanecem a fé, a esperança e o amor; mas o maior destes é o amor.', '1 Corinthians 13:13', 'And now these three remain: faith, hope and love. But the greatest of these is love.', '1 Corintios 13:13', 'Y ahora permanecen la fe, la esperanza y el amor, estos tres; pero el mayor de ellos es el amor.'),
    ('1 João 4:8', 'Deus é amor; e quem permanece em amor permanece em Deus.', '1 John 4:8', 'God is love. Whoever lives in love lives in God.', '1 Juan 4:8', 'Dios es amor. El que permanece en amor, permanece en Dios.'),
    ('João 13:34', 'Amai-vos uns aos outros; assim como eu vos amei.', 'John 13:34', 'Love one another; as I have loved you, so you must love one another.', 'Juan 13:34', 'Que os améis unos a otros; como yo os he amado.'),
    ('Romanos 5:5', 'O amor de Deus está derramado em nossos corações pelo Espírito Santo.', 'Romans 5:5', "God's love has been poured out into our hearts through the Holy Spirit.", 'Romanos 5:5', 'El amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo.'),
    ('Salmo 136:1', 'Louvai ao Senhor, porque ele é bom, porque a sua benignidade dura para sempre.', 'Psalm 136:1', 'Give thanks to the Lord, for he is good; his love endures forever.', 'Salmo 136:1', 'Alabad al Señor, porque es bueno, porque para siempre es su misericordia.'),
    ('1 João 4:19', 'Nós amamos porque ele nos amou primeiro.', '1 John 4:19', 'We love because he first loved us.', '1 Juan 4:19', 'Nosotros le amamos a él, porque él nos amó primero.'),
    ('Colossenses 3:14', 'E, sobre tudo isto, revesti-vos de amor, que é o vínculo da perfeição.', 'Colossians 3:14', 'And over all these virtues put on love, which binds them all together in perfect unity.', 'Colosenses 3:14', 'Y sobre todas estas cosas vestíos de amor, que es el vínculo perfecto.'),
    ('Efésios 4:32', 'Sede bondosos e compassivos uns para com os outros, perdoando-vos mutuamente.', 'Ephesians 4:32', 'Be kind and compassionate to one another, forgiving each other.', 'Efesios 4:32', 'Sed benignos unos con otros, misericordiosos, perdonándoos unos a otros.'),
    ('Salmo 103:8', 'O Senhor é misericordioso e piedoso; lento em irar-se e grande em benignidade.', 'Psalm 103:8', 'The Lord is compassionate and gracious, slow to anger, abounding in love.', 'Salmo 103:8', 'Misericordioso y clemente es el Señor; lento para la ira, y grande en misericordia.'),
    ('Provérbios 17:17', 'Em todo o tempo ama o amigo; e na angústia nasce o irmão.', 'Proverbs 17:17', 'A friend loves at all times, and a brother is born for a time of adversity.', 'Proverbios 17:17', 'En todo tiempo ama el amigo; y el hermano es para el tiempo de angustia.'),
    ('João 15:12', 'O meu mandamento é este: que vos ameis uns aos outros, assim como eu vos amei.', 'John 15:12', 'My command is this: Love each other as I have loved you.', 'Juan 15:12', 'Este es mi mandamiento: Que os améis unos a otros, como yo os he amado.'),
    ('1 Pedro 4:8', 'Tende amor intenso uns para com os outros, porque o amor cobre a multidão de pecados.', '1 Peter 4:8', 'Love each other deeply, because love covers over a multitude of sins.', '1 Pedro 4:8', 'Tened amor ferviente unos con otros, porque el amor cubrirá multitud de pecados.'),
    ('Salmo 108:4', 'A tua benignidade se eleva até aos céus, e a tua fidelidade até às nuvens.', 'Psalm 108:4', 'Your love, God, reaches to the heavens; your faithfulness to the skies.', 'Salmo 108:4', 'Porque grande es tu misericordia sobre los cielos, y hasta los cielos tu verdad.'),
    ('2 Timóteo 1:7', 'Deus não nos deu o espírito de temor, mas de poder, amor e moderação.', '2 Timothy 1:7', 'God has not given us a spirit of fear, but of power, love and self-discipline.', '2 Timoteo 1:7', 'No nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio.'),
    ('Salmo 66:20', 'Bendito seja Deus, que não rejeitou a minha oração, nem desviou de mim a sua benignidade.', 'Psalm 66:20', 'Praise be to God, who has not rejected my prayer or withheld his love from me.', 'Salmo 66:20', 'Bendito sea Dios, que no echó de mí mi oración, ni de mí su misericordia.'),
    ('João 3:16', 'Deus amou o mundo de tal maneira que deu o seu Filho unigênito.', 'John 3:16', 'For God so loved the world that he gave his one and only Son.', 'Juan 3:16', 'De tal manera amó Dios al mundo, que ha dado a su Hijo unigénito.'),
    ('Salmo 59:16', 'Cantarei o teu poder; pela manhã louvarei a tua benignidade.', 'Psalm 59:16', 'I will sing of your strength; in the morning I will sing of your love.', 'Salmo 59:16', 'Yo cantaré tu poder, y alabaré de mañana tu misericordia.'),
    ('1 João 3:18', 'Não amemos de palavra nem de língua, mas de fato e de verdade.', '1 John 3:18', 'Let us not love with words or speech but with actions and in truth.', '1 Juan 3:18', 'No amemos de palabra ni de lengua, sino de hecho y en verdad.'),
    ('Efésios 3:20', 'Àquele que é poderoso para fazer tudo muito mais abundantemente além do que pedimos.', 'Ephesians 3:20', 'God is able to do immeasurably more than all we ask or imagine.', 'Efesios 3:20', 'A aquel que es poderoso para hacer todas las cosas mucho más abundantemente de lo que pedimos.'),
    ('Salmo 36:7', 'Como é preciosa a tua benignidade, ó Deus! Os filhos dos homens se refugiam à sombra das tuas asas.', 'Psalm 36:7', 'How priceless is your unfailing love, O God! People take refuge in the shadow of your wings.', 'Salmo 36:7', '¡Cuán preciosa, oh Dios, es tu misericordia! Los hijos de los hombres se amparan bajo la sombra de tus alas.'),
    ('Mateus 22:37', 'Amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma e de todo o teu entendimento.', 'Matthew 22:37', 'Love the Lord your God with all your heart and with all your soul and with all your mind.', 'Mateo 22:37', 'Amarás al Señor tu Dios con todo tu corazón, y con toda tu alma, y con toda tu mente.'),
    ('Salmo 31:24', 'Esforçai-vos, e fortaleça-se o vosso coração, vós todos que esperais no Senhor.', 'Psalm 31:24', 'Be strong and take heart, all you who hope in the Lord.', 'Salmo 31:24', 'Esforzaos todos vosotros los que esperáis en el Señor, y tome aliento vuestro corazón.'),
    ('1 Coríntios 16:14', 'Todas as vossas coisas sejam feitas com amor.', '1 Corinthians 16:14', 'Do everything in love.', '1 Corintios 16:14', 'Todas vuestras cosas sean hechas con amor.'),
    ('Salmo 23:6', 'Certamente a bondade e a misericórdia me seguirão todos os dias da minha vida.', 'Psalm 23:6', 'Surely goodness and mercy will follow me all the days of my life.', 'Salmo 23:6', 'Ciertamente el bien y la misericordia me seguirán todos los días de mi vida.'),
    ('Gálatas 5:22', 'O fruto do Espírito é amor, alegria, paz, longanimidade, benignidade e bondade.', 'Galatians 5:22', 'The fruit of the Spirit is love, joy, peace, forbearance, kindness and goodness.', 'Gálatas 5:22', 'El fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad.'),
    ('Salmo 33:5', 'Ele ama a justiça e o juízo; a terra está cheia da bondade do Senhor.', 'Psalm 33:5', 'The Lord loves righteousness and justice; the earth is full of his unfailing love.', 'Salmo 33:5', 'Él ama la justicia y el derecho; de la misericordia del Señor está llena la tierra.'),
    ('1 Coríntios 13:7', 'Tudo sofre, tudo crê, tudo espera, tudo suporta.', '1 Corinthians 13:7', 'It always protects, always trusts, always hopes, always perseveres.', '1 Corintios 13:7', 'Todo lo sufre, todo lo cree, todo lo espera, todo lo soporta.'),
    ('Salmo 119:76', 'Seja, pois, a tua benignidade a minha consolação, segundo a tua promessa ao teu servo.', 'Psalm 119:76', 'May your unfailing love be my comfort, according to your promise to your servant.', 'Salmo 119:76', 'Sea tu misericordia mi consuelo, conforme a tu palabra dada a tu siervo.'),
    ('Jeremias 31:3', 'Com amor eterno te amei; por isso, com benignidade te atraí.', 'Jeremiah 31:3', 'I have loved you with an everlasting love; I have drawn you with unfailing kindness.', 'Jeremías 31:3', 'Con amor eterno te he amado; por tanto, te prolongué mi misericordia.'),
    ('Isaías 40:29', 'Ele dá força ao cansado e multiplica as forças ao que não tem nenhum vigor.', 'Isaiah 40:29', 'He gives strength to the weary and increases the power of the weak.', 'Isaías 40:29', 'Él da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.'),
    ('Deuteronômio 31:6', 'Esforçai-vos e animai-vos; o Senhor vosso Deus não vos deixará, nem vos desamparará.', 'Deuteronomy 31:6', 'Be strong and courageous; the Lord your God will not leave you nor forsake you.', 'Deuteronomio 31:6', 'Esforzaos y cobrad ánimo; no temáis, porque el Señor tu Dios no te dejará, ni te desamparará.'),
    ('2 Coríntios 12:9', 'A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza.', '2 Corinthians 12:9', 'My grace is sufficient for you, for my power is made perfect in weakness.', '2 Corintios 12:9', 'Te basta mi gracia; porque mi poder se perfecciona en la debilidad.'),
    ('Salmo 27:1', 'O Senhor é a minha luz e a minha salvação; a quem temerei?', 'Psalm 27:1', 'The Lord is my light and my salvation; whom shall I fear?', 'Salmo 27:1', 'El Señor es mi luz y mi salvación; ¿de quién temeré?'),
    ('Neemias 8:10', 'A alegria do Senhor é a vossa força.', 'Nehemiah 8:10', 'The joy of the Lord is your strength.', 'Nehemías 8:10', 'El gozo del Señor es vuestra fuerza.'),
    ('Salmo 18:32', 'Deus é o que me cinge de força e aperfeiçoa o meu caminho.', 'Psalm 18:32', 'It is God who arms me with strength and keeps my way secure.', 'Salmo 18:32', 'Dios es el que me ciñe de vigor, y quien hace perfecto mi camino.'),
    ('Efésios 6:10', 'Fortalecei-vos no Senhor e na força do seu poder.', 'Ephesians 6:10', 'Be strong in the Lord and in his mighty power.', 'Efesios 6:10', 'Fortaleceos en el Señor, y en el poder de su fuerza.'),
    ('Salmo 68:35', 'O Deus de Israel é o que dá força e poder ao seu povo; bendito seja Deus.', 'Psalm 68:35', 'The God of Israel gives power and strength to his people. Praise be to God!', 'Salmo 68:35', 'El Dios de Israel da fuerza y vigor a su pueblo. Bendito sea Dios.'),
    ('2 Timóteo 2:1', 'Fortalece-te na graça que há em Cristo Jesus.', '2 Timothy 2:1', 'Be strong in the grace that is in Christ Jesus.', '2 Timoteo 2:1', 'Esfuérzate en la gracia que es en Cristo Jesús.'),
    ('Salmo 71:16', 'Virei com a força do Senhor Deus; farei menção da tua justiça.', 'Psalm 71:16', 'I will come and proclaim your mighty acts, Sovereign Lord; I will proclaim your righteous deeds.', 'Salmo 71:16', 'Vendré con la potencia de Dios; haré mención de tu justicia.'),
    ('Isaías 12:2', 'Eis que Deus é a minha salvação; confiarei e não temerei.', 'Isaiah 12:2', 'Surely God is my salvation; I will trust and not be afraid.', 'Isaías 12:2', 'He aquí, Dios es mi salvación; confiaré y no temeré.'),
    ('Salmo 138:3', 'No dia em que eu clamei, respondeste-me; aumentaste a força da minha alma.', 'Psalm 138:3', 'When I called, you answered me; you made me bold and stouthearted.', 'Salmo 138:3', 'El día que clamé, me respondiste; me fortaleciste con vigor en mi alma.'),
    ('Provérbios 24:10', 'Se te mostrares fraco no dia da angústia, a tua força é pequena.', 'Proverbs 24:10', 'If you falter in a time of trouble, how small is your strength!', 'Proverbios 24:10', 'Si fueres flojo en el día de trabajo, tu fuerza será reducida.'),
    ('Salmo 84:5', 'Bem-aventurado o homem cuja força está em ti, em cujo coração estão os caminhos do Senhor.', 'Psalm 84:5', 'Blessed are those whose strength is in you, whose hearts are set on pilgrimage.', 'Salmo 84:5', 'Bienaventurado el hombre que tiene en ti sus fuerzas, en cuyo corazón están tus caminos.'),
    ('1 Crônicas 16:11', 'Buscai ao Senhor e a sua força; buscai a sua face continuamente.', '1 Chronicles 16:11', 'Look to the Lord and his strength; seek his face always.', '1 Crónicas 16:11', 'Buscad al Señor y su poder; buscad su rostro continuamente.'),
    ('Salmo 46:10', 'Aquietai-vos e sabei que eu sou Deus; serei exaltado entre as nações.', 'Psalm 46:10', 'Be still, and know that I am God; I will be exalted among the nations.', 'Salmo 46:10', 'Estad quietos, y conoced que yo soy Dios; seré exaltado entre las naciones.'),
    ('Habacuque 3:19', 'O Senhor Deus é a minha força, e fará os meus pés como os da corça.', 'Habakkuk 3:19', 'The Sovereign Lord is my strength; he makes my feet like the feet of a deer.', 'Habacuc 3:19', 'El Señor Dios es mi fortaleza, el cual hace mis pies como de ciervas.'),
    ('Salmo 63:1', 'Ó Deus, tu és o meu Deus; de madrugada te buscarei.', 'Psalm 63:1', 'You, God, are my God, earnestly I seek you; I thirst for you.', 'Salmo 63:1', 'Dios, Dios mío eres tú; de madrugada te buscaré.'),
    ('2 Crônicas 15:7', 'Sede fortes, e não desfaleçam as vossas mãos; a vossa obra tem recompensa.', '2 Chronicles 15:7', 'Be strong and do not give up, for your work will be rewarded.', '2 Crónicas 15:7', 'Esforzaos, y no desfallezcan vuestras manos, pues hay recompensa para vuestra obra.'),
    ('Salmo 29:11', 'O Senhor dará força ao seu povo; o Senhor abençoará o seu povo com paz.', 'Psalm 29:11', 'The Lord gives strength to his people; the Lord blesses his people with peace.', 'Salmo 29:11', 'El Señor dará poder a su pueblo; el Señor bendecirá a su pueblo con paz.'),
    ('1 Reis 19:7', 'Levanta-te e come, porque muito caminho te resta.', '1 Kings 19:7', 'Get up and eat, for the journey is too much for you.', '1 Reyes 19:7', 'Levántate, come; porque largo camino te resta.'),
    ('Salmo 119:28', 'A minha alma consome-se de tristeza; fortalece-me segundo a tua palavra.', 'Psalm 119:28', 'My soul is weary with sorrow; strengthen me according to your word.', 'Salmo 119:28', 'Se deshace mi alma de ansiedad; susténtame conforme a tu palabra.'),
    ('Isaías 26:3', 'Tu conservarás em perfeita paz aquele cuja mente está firme em ti.', 'Isaiah 26:3', 'You will keep in perfect peace those whose minds are steadfast, because they trust in you.', 'Isaías 26:3', 'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera.'),
    ('Salmo 91:11', 'Porque aos seus anjos dará ordem a teu respeito, para te guardarem em todos os teus caminhos.', 'Psalm 91:11', 'For he will command his angels concerning you to guard you in all your ways.', 'Salmo 91:11', 'Pues a sus ángeles mandará acerca de ti, que te guarden en todos tus caminos.'),
    ('1 Pedro 5:7', 'Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.', '1 Peter 5:7', 'Cast all your anxiety on him because he cares for you.', '1 Pedro 5:7', 'Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros.'),
    ('Salmo 16:8', 'Tenho posto o Senhor continuamente diante de mim; por isso não serei abalado.', 'Psalm 16:8', 'I keep my eyes always on the Lord. With him at my right hand, I will not be shaken.', 'Salmo 16:8', 'A Jehová he puesto siempre delante de mí; porque está a mi diestra, no seré conmovido.'),
    ('Romanos 8:31', 'Se Deus é por nós, quem será contra nós?', 'Romans 8:31', 'If God is for us, who can be against us?', 'Romanos 8:31', 'Si Dios es por nosotros, ¿quién contra nosotros?'),
    ('Salmo 37:24', 'Ainda que caia, não ficará prostrado, pois o Senhor o sustém com a sua mão.', 'Psalm 37:24', 'Though he may stumble, he will not fall, for the Lord upholds him with his hand.', 'Salmo 37:24', 'Cuando cayere, no quedará postrado, porque el Señor sostiene su mano.'),
    ('Isaías 54:17', 'Nenhuma arma forjada contra ti prosperará.', 'Isaiah 54:17', 'No weapon forged against you will prevail.', 'Isaías 54:17', 'Ninguna arma forjada contra ti prosperará.'),
    ('Salmo 27:14', 'Espera no Senhor, anima-te, e ele fortalecerá o teu coração.', 'Psalm 27:14', 'Wait for the Lord; be strong and take heart and wait for the Lord.', 'Salmo 27:14', 'Espera en el Señor; esfuérzate, y aliéntese tu corazón.'),
    ('Tiago 1:5', 'Se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente.', 'James 1:5', 'If any of you lacks wisdom, you should ask God, who gives generously to all.', 'Santiago 1:5', 'Si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente.'),
    ('Provérbios 2:6', 'Porque o Senhor dá a sabedoria; da sua boca procedem o conhecimento e o entendimento.', 'Proverbs 2:6', 'For the Lord gives wisdom; from his mouth come knowledge and understanding.', 'Proverbios 2:6', 'Porque el Señor da la sabiduría, y de su boca viene el conocimiento y la inteligencia.'),
    ('Salmo 119:105', 'Lâmpada para os meus pés é a tua palavra e luz para o meu caminho.', 'Psalm 119:105', 'Your word is a lamp for my feet, a light on my path.', 'Salmo 119:105', 'Lámpara es a mis pies tu palabra, y lumbrera a mi camino.'),
    ('Provérbios 3:6', 'Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.', 'Proverbs 3:6', 'In all your ways submit to him, and he will make your paths straight.', 'Proverbios 3:6', 'Reconócelo en todos tus caminos, y él enderezará tus veredas.'),
    ('Salmo 25:12', 'Qual é o homem que teme ao Senhor? Ele o ensinará no caminho que deve escolher.', 'Psalm 25:12', 'Who, then, are those who fear the Lord? He will instruct them in the ways they should choose.', 'Salmo 25:12', '¿Quién es el hombre que teme al Señor? Él le enseñará el camino que ha de escoger.'),
    ('Provérbios 4:7', 'A sabedoria é a coisa principal; adquire, pois, a sabedoria.', 'Proverbs 4:7', 'The beginning of wisdom is this: Get wisdom.', 'Proverbios 4:7', 'Sabiduría ante todo; adquiere sabiduría.'),
    ('Salmo 32:8', 'Instruir-te-ei e ensinar-te-ei o caminho que deves seguir.', 'Psalm 32:8', 'I will instruct you and teach you in the way you should go.', 'Salmo 32:8', 'Te haré entender y te enseñaré el camino en que debes andar.'),
    ('Provérbios 11:2', 'Com os humildes está a sabedoria.', 'Proverbs 11:2', 'With humility comes wisdom.', 'Proverbios 11:2', 'Con los humildes está la sabiduría.'),
    ('Salmo 119:130', 'A entrada das tuas palavras dá luz, e dá entendimento aos símplices.', 'Psalm 119:130', 'The unfolding of your words gives light; it gives understanding to the simple.', 'Salmo 119:130', 'La exposición de tus palabras alumbra; hace entender a los simples.'),
    ('1 Coríntios 1:25', 'A loucura de Deus é mais sábia que os homens.', '1 Corinthians 1:25', 'The foolishness of God is wiser than human wisdom.', '1 Corintios 1:25', 'Lo insensato de Dios es más sabio que los hombres.'),
    ('Provérbios 16:16', 'Quanto melhor é adquirir a sabedoria do que o ouro!', 'Proverbs 16:16', 'How much better to get wisdom than gold!', 'Proverbios 16:16', 'Mejor es adquirir sabiduría que oro preciado.'),
    ('Salmo 119:66', 'Ensina-me bom senso e conhecimento, pois cri nos teus mandamentos.', 'Psalm 119:66', 'Teach me knowledge and good judgment, for I trust your commands.', 'Salmo 119:66', 'Enséñame buen sentido y sabiduría, porque tus mandamientos he creído.'),
    ('Eclesiastes 7:12', 'A sabedoria é uma proteção, como o dinheiro o é; mas a excelência do conhecimento é que a sabedoria dá vida.', 'Ecclesiastes 7:12', 'Wisdom is a shelter, as money is a shelter, but the advantage of knowledge is this: Wisdom preserves those who have it.', 'Eclesiastés 7:12', 'Sabiduría es protección, como también el dinero; pero la excelencia del conocimiento es que la sabiduría da vida.'),
    ('Provérbios 19:21', 'Muitos são os planos no coração do homem, mas o conselho do Senhor permanecerá.', 'Proverbs 19:21', "Many are the plans in a person's heart, but it is the Lord's purpose that prevails.", 'Proverbios 19:21', 'Muchos son los planes en el corazón del hombre, pero el consejo del Señor permanecerá.'),
    ('Salmo 119:9', 'Com que purificará o jovem o seu caminho? Observando-o conforme a tua palavra.', 'Psalm 119:9', 'How can a young person stay on the path of purity? By living according to your word.', 'Salmo 119:9', '¿Con qué limpiará el joven su camino? Con guardar tu palabra.'),
    ('Provérbios 15:22', 'Onde não há conselho fracassam os projetos; com muitos conselheiros há êxito.', 'Proverbs 15:22', 'Plans fail for lack of counsel, but with many advisers they succeed.', 'Proverbios 15:22', 'Los pensamientos son frustrados donde no hay consejo; mas en la multitud de consejeros se afirman.'),
    ('Salmo 37:23', 'Os passos de um homem bom são confirmados pelo Senhor, e ele se deleita no seu caminho.', 'Psalm 37:23', 'The Lord makes firm the steps of the one who delights in his way.', 'Salmo 37:23', 'Por el Señor son ordenados los pasos del hombre, y él se complace en su camino.'),
    ('2 Timóteo 3:16', 'Toda a Escritura é inspirada por Deus e útil para ensinar, redarguir, corrigir e instruir.', '2 Timothy 3:16', 'All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training.', '2 Timoteo 3:16', 'Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir.'),
    ('Salmo 119:11', 'Escondi a tua palavra no meu coração, para eu não pecar contra ti.', 'Psalm 119:11', 'I have hidden your word in my heart that I might not sin against you.', 'Salmo 119:11', 'En mi corazón he guardado tus dichos, para no pecar contra ti.'),
    ('Provérbios 8:11', 'Porque melhor é a sabedoria do que os rubins, e todas as coisas desejáveis não se podem comparar com ela.', 'Proverbs 8:11', 'For wisdom is more precious than rubies, and nothing you desire compares with her.', 'Proverbios 8:11', 'Porque mejor es la sabiduría que las piedras preciosas; y todo cuanto se desee no se compara a ella.'),
    ('Salmo 143:10', 'Ensina-me a fazer a tua vontade, pois tu és o meu Deus.', 'Psalm 143:10', 'Teach me to do your will, for you are my God.', 'Salmo 143:10', 'Enséñame a hacer tu voluntad, porque tú eres mi Dios.'),
    ('Provérbios 1:7', 'O temor do Senhor é o princípio da ciência; os loucos desprezam a sabedoria e a instrução.', 'Proverbs 1:7', 'The fear of the Lord is the beginning of knowledge, but fools despise wisdom and instruction.', 'Proverbios 1:7', 'El principio de la sabiduría es el temor del Señor; los insensatos desprecian la sabiduría y la enseñanza.'),
    ('Salmo 119:73', 'As tuas mãos me fizeram e me formaram; dá-me entendimento para aprender os teus mandamentos.', 'Psalm 119:73', 'Your hands made me and formed me; give me understanding to learn your commands.', 'Salmo 119:73', 'Tus manos me hicieron y me formaron; hazme entender, y aprenderé tus mandamientos.'),
    ('Colossenses 2:3', 'No qual estão escondidos todos os tesouros da sabedoria e do conhecimento.', 'Colossians 2:3', 'In whom are hidden all the treasures of wisdom and knowledge.', 'Colosenses 2:3', 'En quien están escondidos todos los tesoros de la sabiduría y del conocimiento.'),
    ('Salmo 119:169', 'Chegue a ti o meu clamor, ó Senhor; dá-me entendimento segundo a tua palavra.', 'Psalm 119:169', 'May my cry come before you, Lord; give me understanding according to your word.', 'Salmo 119:169', 'Llegue mi clamor delante de ti, oh Señor; dame entendimiento conforme a tu palabra.'),
    ('Provérbios 3:13', 'Bem-aventurado o homem que acha a sabedoria, e o homem que adquire o entendimento.', 'Proverbs 3:13', 'Blessed are those who find wisdom, those who gain understanding.', 'Proverbios 3:13', 'Bienaventurado el hombre que halla la sabiduría, y que obtiene la inteligencia.'),
    ('Salmo 90:12', 'Ensina-nos a contar os nossos dias, de tal maneira que alcancemos corações sábios.', 'Psalm 90:12', 'Teach us to number our days, that we may gain a heart of wisdom.', 'Salmo 90:12', 'Enséñanos a contar de tal modo nuestros días, que traigamos al corazón sabiduría.'),
    ('Provérbios 22:17', 'Inclina o teu ouvido e ouve as palavras dos sábios, e aplica o teu coração à minha ciência.', 'Proverbs 22:17', 'Pay attention and turn your ear to the sayings of the wise; apply your heart to what I teach.', 'Proverbios 22:17', 'Inclina tu oído y oye las palabras de los sabios, y aplica tu corazón a mi sabiduría.'),
    ('Salmo 119:125', 'Sou teu servo; dá-me entendimento, para que conheça os teus testemunhos.', 'Psalm 119:125', 'I am your servant; give me discernment that I may understand your statutes.', 'Salmo 119:125', 'Yo soy tu siervo; dame entendimiento, y conoceré tus testimonios.'),
    ('Provérbios 14:15', 'O simples dá crédito a cada palavra, mas o prudente atenta para os seus passos.', 'Proverbs 14:15', 'The simple believe anything, but the prudent give thought to their steps.', 'Proverbios 14:15', 'El simple todo lo cree; mas el avisado mira bien sus pasos.'),
    ('Salmo 100:4', 'Entrai pelas portas dele com gratidão, e em seus átrios com louvor.', 'Psalm 100:4', 'Enter his gates with thanksgiving and his courts with praise.', 'Salmo 100:4', 'Entrad por sus puertas con acción de gracias, por sus atrios con alabanza.'),
    ('1 Tessalonicenses 5:18', 'Em tudo dai graças, porque esta é a vontade de Deus em Cristo Jesus para convosco.', '1 Thessalonians 5:18', "Give thanks in all circumstances; for this is God's will for you in Christ Jesus.", '1 Tesalonicenses 5:18', 'Dad gracias en todo, porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.'),
    ('Salmo 95:2', 'Apresentemo-nos diante dele com louvor e celebremo-lo com salmos.', 'Psalm 95:2', 'Let us come before him with thanksgiving and extol him with music and song.', 'Salmo 95:2', 'Lleguemos ante su presencia con alabanza; aclamémosle con cánticos.'),
    ('Salmo 107:1', 'Louvai ao Senhor, porque ele é bom, porque a sua benignidade dura para sempre.', 'Psalm 107:1', 'Give thanks to the Lord, for he is good; his love endures forever.', 'Salmo 107:1', 'Alabad al Señor, porque él es bueno, porque para siempre es su misericordia.'),
    ('Filipenses 4:4', 'Regozijai-vos sempre no Senhor; outra vez digo: regozijai-vos.', 'Philippians 4:4', 'Rejoice in the Lord always. I will say it again: Rejoice!', 'Filipenses 4:4', 'Regocijaos en el Señor siempre. Otra vez digo: ¡Regocijaos!'),
    ('Salmo 103:1', 'Bendize, ó minha alma, ao Senhor, e tudo o que há em mim bendiga o seu santo nome.', 'Psalm 103:1', 'Praise the Lord, my soul; all my inmost being, praise his holy name.', 'Salmo 103:1', 'Bendice, alma mía, al Señor, y bendiga todo mi ser su santo nombre.'),
    ('Salmo 92:1', 'Bom é louvar ao Senhor, e cantar louvores ao teu nome, ó Altíssimo.', 'Psalm 92:1', 'It is good to praise the Lord and make music to your name, O Most High.', 'Salmo 92:1', 'Bueno es alabarte, oh Señor, y cantar salmos a tu nombre, oh Altísimo.'),
    ('Salmo 30:4', 'Cantai ao Senhor, vós que sois seus santos, e louvai a memória da sua santidade.', 'Psalm 30:4', 'Sing the praises of the Lord, you his faithful people; praise his holy name.', 'Salmo 30:4', 'Cantad a él, santos suyos, y alabad la memoria de su santidad.'),
    ('Salmo 100:1', 'Celebrai com júbilo ao Senhor, todas as terras.', 'Psalm 100:1', 'Shout for joy to the Lord, all the earth.', 'Salmo 100:1', 'Cantad alegres a Dios, habitantes de toda la tierra.'),
    ('Salmo 103:2', 'Bendize, ó minha alma, ao Senhor, e não te esqueças de nenhum dos seus benefícios.', 'Psalm 103:2', 'Praise the Lord, my soul, and forget not all his benefits.', 'Salmo 103:2', 'Bendice, alma mía, al Señor, y no olvides ninguno de sus beneficios.'),
    ('Salmo 118:1', 'Louvai ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre.', 'Psalm 118:1', 'Give thanks to the Lord, for he is good; his love endures forever.', 'Salmo 118:1', 'Alabad al Señor, porque es bueno; porque para siempre es su misericordia.'),
    ('Salmo 9:1', 'Louvar-te-ei, ó Senhor, de todo o meu coração; contarei todas as tuas maravilhas.', 'Psalm 9:1', 'I will give thanks to you, Lord, with all my heart; I will tell of all your wonderful deeds.', 'Salmo 9:1', 'Te alabaré, oh Señor, con todo mi corazón; contaré todas tus maravillas.'),
    ('Salmo 50:23', 'Aquele que oferece sacrifício de louvor me glorifica.', 'Psalm 50:23', 'Those who sacrifice thank offerings honor me.', 'Salmo 50:23', 'El que sacrifica alabanza me honra.'),
    ('Salmo 147:1', 'Louvai ao Senhor, porque é bom cantar louvores ao nosso Deus.', 'Psalm 147:1', 'Praise the Lord. How good it is to sing praises to our God.', 'Salmo 147:1', 'Alabad al Señor, porque es bueno cantar salmos a nuestro Dios.'),
    ('Salmo 136:26', 'Louvai ao Deus dos céus, porque a sua benignidade dura para sempre.', 'Psalm 136:26', 'Give thanks to the God of heaven, for his love endures forever.', 'Salmo 136:26', 'Alabad al Dios de los cielos, porque para siempre es su misericordia.'),
    ('Salmo 100:2', 'Servi ao Senhor com alegria; apresentai-vos diante dele com cântico.', 'Psalm 100:2', 'Worship the Lord with gladness; come before him with joyful songs.', 'Salmo 100:2', 'Servid al Señor con alegría; venid ante su presencia con regocijo.'),
    ('Salmo 106:1', 'Louvai ao Senhor, porque ele é bom, porque a sua benignidade dura para sempre.', 'Psalm 106:1', 'Praise the Lord. Give thanks to the Lord, for he is good; his love endures forever.', 'Salmo 106:1', 'Alabad al Señor, porque es bueno, porque para siempre es su misericordia.'),
    ('Salmo 150:6', 'Tudo quanto tem fôlego louve ao Senhor. Louvai ao Senhor.', 'Psalm 150:6', 'Let everything that has breath praise the Lord. Praise the Lord.', 'Salmo 150:6', 'Todo lo que respira alabe al Señor. Alabad al Señor.'),
    ('Salmo 116:17', 'Oferecer-te-ei sacrifício de louvor e invocarei o nome do Senhor.', 'Psalm 116:17', 'I will sacrifice a thank offering to you and call on the name of the Lord.', 'Salmo 116:17', 'Te ofreceré sacrificio de alabanza, e invocaré el nombre del Señor.'),
    ('Salmo 34:1', 'Bendirei ao Senhor em todo o tempo; o seu louvor estará continuamente na minha boca.', 'Psalm 34:1', 'I will extol the Lord at all times; his praise will always be on my lips.', 'Salmo 34:1', 'Bendeciré al Señor en todo tiempo; su alabanza estará de continuo en mi boca.'),
    ('Salmo 113:3', 'Desde o nascer do sol até ao seu ocaso, seja louvado o nome do Senhor.', 'Psalm 113:3', 'From the rising of the sun to the place where it sets, the name of the Lord is to be praised.', 'Salmo 113:3', 'Desde el nacimiento del sol hasta donde se pone, sea alabado el nombre del Señor.'),
    ('Salmo 40:3', 'E pôs um cântico novo na minha boca, um louvor ao nosso Deus.', 'Psalm 40:3', 'He put a new song in my mouth, a hymn of praise to our God.', 'Salmo 40:3', 'Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios.'),
    ('Salmo 95:1', 'Vinde, cantemos ao Senhor; jubilemos à rocha da nossa salvação.', 'Psalm 95:1', 'Come, let us sing for joy to the Lord; let us shout aloud to the Rock of our salvation.', 'Salmo 95:1', 'Venid, cantemos alegres al Señor; cantemos con júbilo a la roca de nuestra salvación.'),
    ('Salmo 8:9', 'Ó Senhor, Senhor nosso, quão admirável é o teu nome em toda a terra!', 'Psalm 8:9', 'Lord, our Lord, how majestic is your name in all the earth!', 'Salmo 8:9', 'Oh Señor, Señor nuestro, ¡cuán glorioso es tu nombre en toda la tierra!'),
    ('Salmo 33:1', 'Regozijai-vos no Senhor, vós justos; pois aos retos convém o louvor.', 'Psalm 33:1', 'Sing joyfully to the Lord, you righteous; it is fitting for the upright to praise him.', 'Salmo 33:1', 'Alegraos, oh justos, en el Señor; de los rectos es propia la alabanza.'),
    ('Salmo 100:5', 'Porque o Senhor é bom, e a sua benignidade dura para sempre, e a sua fidelidade de geração em geração.', 'Psalm 100:5', 'For the Lord is good and his love endures forever; his faithfulness continues through all generations.', 'Salmo 100:5', 'Porque el Señor es bueno; para siempre es su misericordia, y su verdad por todas las generaciones.'),
    ('Salmo 96:1', 'Cantai ao Senhor um cântico novo; cantai ao Senhor, todas as terras.', 'Psalm 96:1', 'Sing to the Lord a new song; sing to the Lord, all the earth.', 'Salmo 96:1', 'Cantad al Señor cántico nuevo; cantad al Señor, toda la tierra.'),
    ('Salmo 92:2', 'Anunciar de manhã a tua benignidade, e de noite a tua fidelidade.', 'Psalm 92:2', 'Proclaiming your love in the morning and your faithfulness at night.', 'Salmo 92:2', 'Anunciar por la mañana tu misericordia, y tu fidelidad por las noches.'),
    ('Salmo 103:20', 'Bendizei ao Senhor, anjos seus, magníficos em poder, que cumpris as suas ordens.', 'Psalm 103:20', 'Praise the Lord, you his angels, you mighty ones who do his bidding.', 'Salmo 103:20', 'Bendecid al Señor, vosotros sus ángeles, poderosos en fuerza, que ejecutáis su palabra.'),
    ('Salmo 119:164', 'Sete vezes no dia te louvo, pelos juízos da tua justiça.', 'Psalm 119:164', 'Seven times a day I praise you for your righteous laws.', 'Salmo 119:164', 'Siete veces al día te alabo, a causa de tus justos juicios.'),
    ('João 14:27', 'Deixo-vos a paz, a minha paz vos dou; não se turbe o vosso coração, nem se atemorize.', 'John 14:27', 'Peace I leave with you; my peace I give you. Do not let your hearts be troubled and do not be afraid.', 'Juan 14:27', 'La paz os dejo, mi paz os doy; no se turbe vuestro corazón, ni tenga miedo.'),
    ('Salmo 4:8', 'Em paz também me deitarei e dormirei, porque só tu, Senhor, me fazes habitar em segurança.', 'Psalm 4:8', 'In peace I will lie down and sleep, for you alone, Lord, make me dwell in safety.', 'Salmo 4:8', 'En paz me acostaré, y asimismo dormiré; porque solo tú, Señor, me haces vivir confiado.'),
    ('Isaías 26:3', 'Tu conservarás em perfeita paz aquele cuja mente está firme em ti, porque em ti confia.', 'Isaiah 26:3', 'You will keep in perfect peace those whose minds are steadfast, because they trust in you.', 'Isaías 26:3', 'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera, porque en ti ha confiado.'),
    ('Salmo 29:11', 'O Senhor dará força ao seu povo; o Senhor abençoará o seu povo com paz.', 'Psalm 29:11', 'The Lord gives strength to his people; the Lord blesses his people with peace.', 'Salmo 29:11', 'El Señor dará poder a su pueblo; el Señor bendecirá a su pueblo con paz.'),
    ('Filipenses 4:7', 'A paz de Deus, que excede todo o entendimento, guardará os vossos corações.', 'Philippians 4:7', 'And the peace of God, which transcends all understanding, will guard your hearts.', 'Filipenses 4:7', 'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones.'),
    ('Salmo 46:10', 'Aquietai-vos e sabei que eu sou Deus.', 'Psalm 46:10', 'Be still, and know that I am God.', 'Salmo 46:10', 'Estad quietos, y conoced que yo soy Dios.'),
    ('Mateus 11:29', 'Tomai sobre vós o meu jugo e aprendei de mim, que sou manso e humilde de coração, e encontrareis descanso.', 'Matthew 11:29', 'Take my yoke upon you and learn from me, for I am gentle and humble in heart, and you will find rest.', 'Mateo 11:29', 'Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso.'),
    ('Salmo 55:22', 'Lança o teu cuidado sobre o Senhor, e ele te susterá; nunca permitirá que o justo seja abalado.', 'Psalm 55:22', 'Cast your cares on the Lord and he will sustain you; he will never let the righteous be shaken.', 'Salmo 55:22', 'Echa sobre el Señor tu carga, y él te sustentará; no dejará para siempre caído al justo.'),
    ('1 Pedro 5:7', 'Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.', '1 Peter 5:7', 'Cast all your anxiety on him because he cares for you.', '1 Pedro 5:7', 'Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros.'),
    ('Salmo 23:2', 'Deitar-me faz em verdes pastos, guia-me mansamente a águas tranquilas.', 'Psalm 23:2', 'He makes me lie down in green pastures, he leads me beside quiet waters.', 'Salmo 23:2', 'En lugares de delicados pastos me hará descansar; junto a aguas de reposo me pastoreará.'),
    ('Colossenses 3:15', 'A paz de Deus, para a qual também fostes chamados em um corpo, domine em vossos corações.', 'Colossians 3:15', 'Let the peace of Christ rule in your hearts, since as members of one body you were called to peace.', 'Colosenses 3:15', 'La paz de Cristo gobierne en vuestros corazones, a la cual asimismo fuisteis llamados en un solo cuerpo.'),
    ('Salmo 127:2', 'Assim ele dá aos seus amados o sono.', 'Psalm 127:2', 'For he grants sleep to those he loves.', 'Salmo 127:2', 'Pues a su amado dará Dios el sueño.'),
    ('Romanos 15:13', 'O Deus de esperança vos encha de todo o gozo e paz em crença, para que abundeis em esperança.', 'Romans 15:13', 'May the God of hope fill you with all joy and peace as you trust in him, so that you may overflow with hope.', 'Romanos 15:13', 'El Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza.'),
    ('Salmo 116:7', 'Volta, ó minha alma, para o teu descanso, pois o Senhor te fez bem.', 'Psalm 116:7', 'Return to your rest, my soul, for the Lord has been good to you.', 'Salmo 116:7', 'Vuelve, oh alma mía, a tu reposo, porque el Señor te ha hecho bien.'),
    ('Isaías 32:17', 'O efeito da justiça será paz, e o fruto da justiça, repouso e segurança para sempre.', 'Isaiah 32:17', 'The fruit of that righteousness will be peace; its effect will be quietness and confidence forever.', 'Isaías 32:17', 'El efecto de la justicia será paz, y la labor de la justicia, reposo y seguridad para siempre.'),
    ('Salmo 119:165', 'Muita paz têm os que amam a tua lei, e para eles não há tropeço.', 'Psalm 119:165', 'Great peace have those who love your law, and nothing can make them stumble.', 'Salmo 119:165', 'Mucha paz tienen los que aman tu ley, y no hay para ellos tropiezo.'),
    ('João 16:33', 'Tenho-vos dito isto, para que em mim tenhais paz; no mundo tereis aflições, mas tende bom ânimo.', 'John 16:33', 'I have told you these things, so that in me you may have peace. In this world you will have trouble. But take heart!', 'Juan 16:33', 'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad.'),
    ('Salmo 85:8', 'Ouvirei o que Deus, o Senhor, falar; porque falará de paz ao seu povo.', 'Psalm 85:8', 'I will listen to what God the Lord says; he promises peace to his people.', 'Salmo 85:8', 'Escucharé lo que hablará Dios, el Señor; porque hablará paz a su pueblo.'),
    ('2 Tessalonicenses 3:16', 'O próprio Senhor da paz vos dê paz sempre, em todas as maneiras.', '2 Thessalonians 3:16', 'Now may the Lord of peace himself give you peace at all times and in every way.', '2 Tesalonicenses 3:16', 'El mismo Señor de paz os dé siempre paz en toda manera.'),
    ('Salmo 34:14', 'Aparta-te do mal e faze o bem; procura a paz e segue-a.', 'Psalm 34:14', 'Turn from evil and do good; seek peace and pursue it.', 'Salmo 34:14', 'Apártate del mal, y haz el bien; busca la paz, y síguela.'),
    ('Isaías 48:18', 'Oh! Se tivesses dado ouvidos aos meus mandamentos! Então seria a tua paz como um rio.', 'Isaiah 48:18', 'If only you had paid attention to my commands, your peace would have been like a river.', 'Isaías 48:18', '¡Oh, si hubieras atendido a mis mandamientos! Fuera entonces tu paz como un río.'),
    ('Salmo 42:5', 'Por que estás abatida, ó minha alma? Espera em Deus, pois ainda o louvarei.', 'Psalm 42:5', 'Why, my soul, are you downcast? Put your hope in God, for I will yet praise him.', 'Salmo 42:5', '¿Por qué te abates, oh alma mía? Espera en Dios; porque aún he de alabarle.'),
    ('Salmo 31:14', 'Mas eu confio em ti, ó Senhor; eu digo: Tu és o meu Deus.', 'Psalm 31:14', 'But I trust in you, Lord; I say, You are my God.', 'Salmo 31:14', 'Mas yo en ti confío, oh Señor; digo: Tú eres mi Dios.'),
    ('Filipenses 4:9', 'O que também aprendestes, e recebestes, e ouvistes, e vistes em mim, isso praticai; e o Deus de paz será convosco.', 'Philippians 4:9', 'Whatever you have learned or received or heard from me, or seen in me, put it into practice. And the God of peace will be with you.', 'Filipenses 4:9', 'Lo que aprendisteis y recibisteis y oísteis y visteis en mí, esto haced; y el Dios de paz estará con vosotros.'),
    ('Salmo 3:5', 'Eu me deitei e dormi; acordei, porque o Senhor me sustentou.', 'Psalm 3:5', 'I lie down and sleep; I wake again, because the Lord sustains me.', 'Salmo 3:5', 'Yo me acosté y dormí, y desperté, porque el Señor me sustentaba.'),
    ('Romanos 14:19', 'Sigamos, pois, as coisas que servem para a paz e para a edificação mútua.', 'Romans 14:19', 'Let us therefore make every effort to do what leads to peace and to mutual edification.', 'Romanos 14:19', 'Así que, sigamos lo que contribuye a la paz y a la mutua edificación.'),
    ('Salmo 37:11', 'Mas os mansos herdarão a terra e se deleitarão na abundância de paz.', 'Psalm 37:11', 'But the meek will inherit the land and enjoy peace and prosperity.', 'Salmo 37:11', 'Pero los mansos heredarán la tierra, y se recrearán con abundancia de paz.'),
    ('Isaías 26:12', 'Senhor, tu nos darás a paz, porque tu és o que fizeste em nós todas as nossas obras.', 'Isaiah 26:12', 'Lord, you establish peace for us; all that we have accomplished you have done for us.', 'Isaías 26:12', 'Señor, tú nos darás paz, porque también hiciste en nosotros todas nuestras obras.'),
    ('Salmo 4:4', 'Perturbai-vos e não pequeis; consultai com o vosso coração, em vosso leito, e calai-vos.', 'Psalm 4:4', 'Tremble and do not sin; when you are on your beds, search your hearts and be silent.', 'Salmo 4:4', 'Temblad, y no pequéis; meditad en vuestro corazón estando en vuestra cama, y callad.'),
    ('Números 6:24', 'O Senhor te abençoe e te guarde.', 'Numbers 6:24', 'The Lord bless you and keep you.', 'Números 6:24', 'El Señor te bendiga, y te guarde.'),
    ('Hebreus 10:36', 'Porque necessitais de paciência, para que, depois de haverdes feito a vontade de Deus, possais alcançar a promessa.', 'Hebrews 10:36', 'You need to persevere so that when you have done the will of God, you will receive what he has promised.', 'Hebreos 10:36', 'Porque os es necesaria la paciencia, para que habiendo hecho la voluntad de Dios, obtengáis la promesa.'),
    ('Gálatas 6:9', 'Não nos cansemos de fazer o bem, porque a seu tempo ceifaremos, se não houvermos desfalecido.', 'Galatians 6:9', 'Let us not become weary in doing good, for at the proper time we will reap a harvest if we do not give up.', 'Gálatas 6:9', 'No nos cansemos, pues, de hacer bien; porque a su tiempo segaremos, si no desmayamos.'),
    ('Tiago 1:12', 'Bem-aventurado o homem que suporta a provação; porque, depois de aprovado, receberá a coroa da vida.', 'James 1:12', 'Blessed is the one who perseveres under trial because, having stood the test, that person will receive the crown of life.', 'Santiago 1:12', 'Bienaventurado el varón que soporta la tentación; porque cuando haya sido probado, recibirá la corona de vida.'),
    ('Romanos 5:3', 'Sabemos que a tribulação produz a paciência.', 'Romans 5:3', 'We know that suffering produces perseverance.', 'Romanos 5:3', 'Sabemos que la tribulación produce paciencia.'),
    ('Salmo 40:1', 'Esperei com paciência no Senhor, e ele se inclinou para mim, e ouviu o meu clamor.', 'Psalm 40:1', 'I waited patiently for the Lord; he turned to me and heard my cry.', 'Salmo 40:1', 'Pacientemente esperé al Señor, y se inclinó a mí, y oyó mi clamor.'),
    ('2 Timóteo 4:7', 'Combati o bom combate, acabei a carreira, guardei a fé.', '2 Timothy 4:7', 'I have fought the good fight, I have finished the race, I have kept the faith.', '2 Timoteo 4:7', 'He peleado la buena batalla, he acabado la carrera, he guardado la fe.'),
    ('Salmo 37:7', 'Descansa no Senhor e espera nele; não te indignes por causa daquele que prospera no seu caminho.', 'Psalm 37:7', 'Be still before the Lord and wait patiently for him; do not fret when people succeed in their ways.', 'Salmo 37:7', 'Guarda silencio ante el Señor, y espera en él. No te alteres con motivo del que prospera en su camino.'),
    ('Romanos 12:12', 'Alegrai-vos na esperança; sede pacientes na tribulação; perseverai na oração.', 'Romans 12:12', 'Be joyful in hope, patient in affliction, faithful in prayer.', 'Romanos 12:12', 'Gozaos en la esperanza; sufrid en la tribulación; perseverad en la oración.'),
    ('Salmo 27:14', 'Espera no Senhor; anima-te, e ele fortalecerá o teu coração; espera, pois, no Senhor.', 'Psalm 27:14', 'Wait for the Lord; be strong and take heart and wait for the Lord.', 'Salmo 27:14', 'Espera en el Señor; esfuérzate, y aliéntese tu corazón; sí, espera en el Señor.'),
    ('Hebreus 12:1', 'Corramos com paciência a carreira que nos está proposta.', 'Hebrews 12:1', 'Let us run with perseverance the race marked out for us.', 'Hebreos 12:1', 'Corramos con paciencia la carrera que tenemos por delante.'),
    ('Salmo 130:5', 'Aguardo ao Senhor; a minha alma o aguarda, e espero na sua palavra.', 'Psalm 130:5', 'I wait for the Lord, my whole being waits, and in his word I put my hope.', 'Salmo 130:5', 'Esperé yo al Señor; esperó mi alma en su palabra.'),
    ('Provérbios 14:29', 'O longânimo é grande em entendimento, mas o de espírito impaciente exibe a sua loucura.', 'Proverbs 14:29', 'Whoever is patient has great understanding, but one who is quick-tempered displays folly.', 'Proverbios 14:29', 'El que tarda en airarse es grande de entendimiento; mas el impaciente alza la necedad.'),
    ('Salmo 62:5', 'Ó minha alma, espera somente em Deus, porque dele vem a minha esperança.', 'Psalm 62:5', 'Yes, my soul, find rest in God; my hope comes from him.', 'Salmo 62:5', 'Alma mía, en Dios solamente reposa, porque de él es mi esperanza.'),
    ('Tiago 5:8', 'Sede também vós pacientes; fortalecei os vossos corações, porque a vinda do Senhor está próxima.', 'James 5:8', "You too, be patient and stand firm, because the Lord's coming is near.", 'Santiago 5:8', 'Tened también vosotros paciencia, y afirmad vuestros corazones; porque la venida del Señor se acerca.'),
    ('Salmo 71:14', 'Mas eu esperarei continuamente e te louvarei cada vez mais.', 'Psalm 71:14', 'As for me, I will always have hope; I will praise you more and more.', 'Salmo 71:14', 'Mas yo esperaré siempre, y te alabaré más y más.'),
    ('Romanos 8:25', 'Se esperamos o que não vemos, com paciência o esperamos.', 'Romans 8:25', 'If we hope for what we do not yet have, we wait for it patiently.', 'Romanos 8:25', 'Si esperamos lo que no vemos, con paciencia lo aguardamos.'),
    ('Salmo 39:7', 'Agora, Senhor, que espero eu? A minha esperança está em ti.', 'Psalm 39:7', 'But now, Lord, what do I look for? My hope is in you.', 'Salmo 39:7', 'Y ahora, Señor, ¿qué esperaré? Mi esperanza está en ti.'),
    ('Hebreus 6:12', 'Para que não vos façais negligentes, mas sejais imitadores dos que pela fé e paciência herdam as promessas.', 'Hebrews 6:12', 'We do not want you to become lazy, but to imitate those who through faith and patience inherit what has been promised.', 'Hebreos 6:12', 'Para que no os hagáis perezosos, sino imitadores de aquellos que por la fe y la paciencia heredan las promesas.'),
    ('Salmo 27:13', 'Cri que veria a bondade do Senhor na terra dos viventes.', 'Psalm 27:13', 'I remain confident of this: I will see the goodness of the Lord in the land of the living.', 'Salmo 27:13', 'Hubiera yo desmayado, si no creyera que veré la bondad del Señor en la tierra de los vivientes.'),
    ('1 Coríntios 15:58', 'Sede firmes e constantes, sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão.', '1 Corinthians 15:58', 'Stand firm. Let nothing move you. Always give yourselves fully to the work of the Lord, because your labor is not in vain.', '1 Corintios 15:58', 'Sed firmes y constantes, creciendo en la obra del Señor siempre, sabiendo que vuestro trabajo en el Señor no es en vano.'),
    ('Salmo 33:20', 'A nossa alma espera ao Senhor; ele é o nosso auxílio e o nosso escudo.', 'Psalm 33:20', 'We wait in hope for the Lord; he is our help and our shield.', 'Salmo 33:20', 'Nuestra alma espera al Señor; él es nuestra ayuda y nuestro escudo.'),
    ('Isaías 30:18', 'Bem-aventurados todos os que nele esperam.', 'Isaiah 30:18', 'Blessed are all who wait for him!', 'Isaías 30:18', 'Bienaventurados todos los que en él confían.'),
    ('Salmo 37:34', 'Espera no Senhor e guarda o seu caminho, e ele te exaltará para herdares a terra.', 'Psalm 37:34', 'Hope in the Lord and keep his way. He will exalt you to inherit the land.', 'Salmo 37:34', 'Espera en el Señor, y guarda su camino, y él te exaltará para heredar la tierra.'),
    ('Filipenses 3:14', 'Prossigo para o alvo, pelo prêmio da soberana vocação de Deus em Cristo Jesus.', 'Philippians 3:14', 'I press on toward the goal to win the prize for which God has called me heavenward in Christ Jesus.', 'Filipenses 3:14', 'Prosigo a la meta, al premio del supremo llamamiento de Dios en Cristo Jesús.'),
    ('Salmo 31:24', 'Esforçai-vos, e fortaleça-se o vosso coração, vós todos que esperais no Senhor.', 'Psalm 31:24', 'Be strong and take heart, all you who hope in the Lord.', 'Salmo 31:24', 'Esforzaos todos vosotros los que esperáis en el Señor, y tome aliento vuestro corazón.'),
    ('Lucas 21:19', 'Na vossa paciência possuireis as vossas almas.', 'Luke 21:19', 'Stand firm, and you will win life.', 'Lucas 21:19', 'En vuestra paciencia ganaréis vuestras almas.'),
    ('Salmo 40:17', 'Mas eu sou pobre e necessitado; porém o Senhor cuida de mim.', 'Psalm 40:17', 'But as for me, I am poor and needy; may the Lord think of me.', 'Salmo 40:17', 'Aunque afligido y necesitado, el Señor piensa en mí.'),
    ('Romanos 5:4', 'E a paciência, experiência; e a experiência, esperança.', 'Romans 5:4', 'Perseverance, character; and character, hope.', 'Romanos 5:4', 'Y la paciencia, prueba; y la prueba, esperanza.'),
    ('Salmo 145:15', 'Os olhos de todos esperam em ti, e tu lhes dás o seu mantimento a seu tempo.', 'Psalm 145:15', 'The eyes of all look to you, and you give them their food at the proper time.', 'Salmo 145:15', 'Los ojos de todos esperan en ti, y tú les das su comida a su tiempo.'),
    ('Hebreus 11:1', 'A fé é o firme fundamento das coisas que se esperam e a prova das coisas que não se veem.', 'Hebrews 11:1', 'Now faith is confidence in what we hope for and assurance about what we do not see.', 'Hebreos 11:1', 'Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve.'),
    ('Provérbios 18:21', 'A morte e a vida estão no poder da língua; o que a ama comerá do seu fruto.', 'Proverbs 18:21', 'The tongue has the power of life and death, and those who love it will eat its fruit.', 'Proverbios 18:21', 'La muerte y la vida están en poder de la lengua; el que la ama comerá de sus frutos.'),
    ('Efésios 4:29', 'Não saia da vossa boca nenhuma palavra torpe, mas só a que for boa para a edificação.', 'Ephesians 4:29', 'Do not let any unwholesome talk come out of your mouths, but only what is helpful for building others up.', 'Efesios 4:29', 'Ninguna palabra corrompida salga de vuestra boca, sino la que sea buena para la edificación.'),
    ('Provérbios 15:1', 'A resposta branda desvia o furor, mas a palavra dura suscita a ira.', 'Proverbs 15:1', 'A gentle answer turns away wrath, but a harsh word stirs up anger.', 'Proverbios 15:1', 'La blanda respuesta quita la ira; mas la palabra áspera enciende el enojo.'),
    ('Salmo 19:14', 'Sejam agradáveis as palavras da minha boca e a meditação do meu coração perante a tua face, Senhor.', 'Psalm 19:14', 'May these words of my mouth and this meditation of my heart be pleasing in your sight, Lord.', 'Salmo 19:14', 'Sean gratos los dichos de mi boca y la meditación de mi corazón delante de ti, oh Señor.'),
    ('Provérbios 12:18', 'Há alguns que falam como espada penetrante, mas a língua dos sábios é saúde.', 'Proverbs 12:18', 'The words of the reckless pierce like swords, but the tongue of the wise brings healing.', 'Proverbios 12:18', 'Hay hombres cuyas palabras son como golpes de espada; mas la lengua de los sabios es medicina.'),
    ('Colossenses 4:6', 'A vossa palavra seja sempre com graça, temperada com sal, para saberdes como vos convém responder.', 'Colossians 4:6', 'Let your conversation be always full of grace, seasoned with salt, so that you may know how to answer everyone.', 'Colosenses 4:6', 'Sea vuestra palabra siempre con gracia, sazonada con sal, para que sepáis cómo debéis responder a cada uno.'),
    ('Provérbios 25:11', 'Como maçãs de ouro em salvas de prata, assim é a palavra dita a seu tempo.', 'Proverbs 25:11', 'Like apples of gold in settings of silver is a ruling rightly given.', 'Proverbios 25:11', 'Manzana de oro con figuras de plata es la palabra dicha como conviene.'),
    ('Tiago 1:19', 'Todo o homem seja pronto para ouvir, tardio para falar, tardio para se irar.', 'James 1:19', 'Everyone should be quick to listen, slow to speak and slow to become angry.', 'Santiago 1:19', 'Todo hombre sea pronto para oír, tardo para hablar, tardo para airarse.'),
    ('Provérbios 16:24', 'Palavras agradáveis são como favo de mel: doçura para a alma e saúde para o corpo.', 'Proverbs 16:24', 'Gracious words are a honeycomb, sweet to the soul and healing to the bones.', 'Proverbios 16:24', 'Panal de miel son los dichos suaves; suavidad al alma y medicina para los huesos.'),
    ('Salmo 141:3', 'Põe, ó Senhor, uma guarda à minha boca; guarda a porta dos meus lábios.', 'Psalm 141:3', 'Set a guard over my mouth, Lord; keep watch over the door of my lips.', 'Salmo 141:3', 'Pon guarda a mi boca, oh Señor; guarda la puerta de mis labios.'),
    ('Provérbios 10:19', 'Na multidão de palavras não falta transgressão, mas o que modera os seus lábios é prudente.', 'Proverbs 10:19', 'Sin is not ended by multiplying words, but the prudent hold their tongues.', 'Proverbios 10:19', 'En las muchas palabras no falta pecado; mas el que refrena sus labios es prudente.'),
    ('Eclesiastes 3:7', 'Há tempo de estar calado e tempo de falar.', 'Ecclesiastes 3:7', 'A time to be silent and a time to speak.', 'Eclesiastés 3:7', 'Tiempo de callar, y tiempo de hablar.'),
    ('Provérbios 21:23', 'O que guarda a sua boca e a sua língua guarda a sua alma das angústias.', 'Proverbs 21:23', 'Those who guard their mouths and their tongues keep themselves from calamity.', 'Proverbios 21:23', 'El que guarda su boca y su lengua, su alma guarda de angustias.'),
    ('Mateus 12:36', 'De toda palavra ociosa que os homens disserem hão de dar conta no dia do juízo.', 'Matthew 12:36', 'Everyone will have to give account on the day of judgment for every empty word they have spoken.', 'Mateo 12:36', 'De toda palabra ociosa que hablen los hombres, de ella darán cuenta en el día del juicio.'),
    ('Provérbios 15:4', 'A língua serena é árvore de vida, mas a perversidade nela quebranta o espírito.', 'Proverbs 15:4', 'The soothing tongue is a tree of life, but a perverse tongue crushes the spirit.', 'Proverbios 15:4', 'La lengua apacible es árbol de vida; mas la perversidad de ella es quebrantamiento de espíritu.'),
    ('Salmo 71:24', 'A minha língua falará da tua justiça todo o dia.', 'Psalm 71:24', 'My tongue will tell of your righteous acts all day long.', 'Salmo 71:24', 'Mi lengua también hablará de tu justicia todo el día.'),
    ('Provérbios 17:28', 'Até o tolo, quando se cala, é tido por sábio; e o que cerra os seus lábios é prudente.', 'Proverbs 17:28', 'Even fools are thought wise if they keep silent, and discerning if they hold their tongues.', 'Proverbios 17:28', 'Aun el necio, cuando calla, es contado por sabio; el que cierra sus labios es entendido.'),
    ('Lucas 6:45', 'A boca fala do que está cheio o coração.', 'Luke 6:45', 'Out of the overflow of the heart the mouth speaks.', 'Lucas 6:45', 'De la abundancia del corazón habla la boca.'),
    ('Provérbios 12:25', 'A ansiedade no coração abate o homem, mas a boa palavra o alegra.', 'Proverbs 12:25', 'Anxiety weighs down the heart, but a kind word cheers it up.', 'Proverbios 12:25', 'La congoja en el corazón del hombre lo abate; mas la buena palabra lo alegra.'),
    ('Salmo 37:30', 'A boca do justo fala a sabedoria; a sua língua fala o que é reto.', 'Psalm 37:30', 'The mouths of the righteous utter wisdom, and their tongues speak what is just.', 'Salmo 37:30', 'La boca del justo habla sabiduría, y su lengua habla justicia.'),
    ('Provérbios 13:3', 'O que guarda a sua boca conserva a sua vida, mas o que muito abre os seus lábios terá ruína.', 'Proverbs 13:3', 'Those who guard their lips preserve their lives, but those who speak rashly will come to ruin.', 'Proverbios 13:3', 'El que guarda su boca guarda su alma; mas el que mucho abre sus labios tendrá calamidad.'),
    ('2 Timóteo 2:24', 'O servo do Senhor não deve contender, mas ser manso para com todos.', '2 Timothy 2:24', "The Lord's servant must not be quarrelsome but must be kind to everyone.", '2 Timoteo 2:24', 'El siervo del Señor no debe ser contencioso, sino amable para con todos.'),
    ('Provérbios 16:23', 'O coração do sábio instrui a sua boca e acrescenta doçura aos seus lábios.', 'Proverbs 16:23', 'The hearts of the wise make their mouths prudent, and their lips promote instruction.', 'Proverbios 16:23', 'El corazón del sabio hace prudente su boca, y añade gracia a sus labios.'),
    ('Salmo 34:13', 'Guarda a tua língua do mal e os teus lábios de falarem enganosamente.', 'Psalm 34:13', 'Keep your tongue from evil and your lips from telling lies.', 'Salmo 34:13', 'Guarda tu lengua del mal, y tus labios de hablar engaño.'),
    ('Provérbios 20:15', 'Há ouro e abundância de pedras preciosas, mas os lábios sábios são joia preciosa.', 'Proverbs 20:15', 'Gold there is, and rubies in abundance, but lips that speak knowledge are a rare jewel.', 'Proverbios 20:15', 'Hay oro y multitud de piedras preciosas; mas labios prudentes son joya preciosa.'),
    ('Colossenses 3:16', 'A palavra de Cristo habite em vós abundantemente, em toda a sabedoria, ensinando-vos e admoestando-vos.', 'Colossians 3:16', 'Let the message of Christ dwell among you richly as you teach and admonish one another with all wisdom.', 'Colosenses 3:16', 'La palabra de Cristo more en abundancia en vosotros, enseñándoos y exhortándoos unos a otros.'),
    ('Provérbios 22:11', 'O que ama a pureza de coração, e que tem lábios suaves, será amigo do rei.', 'Proverbs 22:11', 'One who loves a pure heart and who speaks with grace will have the king for a friend.', 'Proverbios 22:11', 'El que ama la limpieza de corazón, por la gracia de sus labios tendrá por amigo al rey.'),
    ('Salmo 119:172', 'Que a minha língua cante a tua palavra, pois todos os teus mandamentos são justos.', 'Psalm 119:172', 'May my tongue sing of your word, for all your commands are righteous.', 'Salmo 119:172', 'Hablará mi lengua tus dichos, porque todos tus mandamientos son justicia.'),
    ('1 Pedro 3:10', 'O que quer amar a vida e ver os dias bons refreie a sua língua do mal.', '1 Peter 3:10', 'Whoever would love life and see good days must keep their tongue from evil.', '1 Pedro 3:10', 'El que quiere amar la vida y ver días buenos, refrene su lengua de mal.'),
    ('Provérbios 10:32', 'Os lábios do justo sabem o que é agradável, mas a boca dos ímpios é perversidade.', 'Proverbs 10:32', 'The lips of the righteous know what finds favor, but the mouth of the wicked only what is perverse.', 'Proverbios 10:32', 'Los labios del justo saben hablar lo agradable; mas la boca de los impíos habla perversidades.'),
    ('Marcos 11:24', 'Tudo o que pedirdes em oração, crede que o recebereis, e tê-lo-eis.', 'Mark 11:24', 'Whatever you ask for in prayer, believe that you have received it, and it will be yours.', 'Marcos 11:24', 'Todo lo que pidiereis orando, creed que lo recibiréis, y os vendrá.'),
    ('Hebreus 11:6', 'Sem fé é impossível agradar a Deus, pois quem dele se aproxima deve crer que ele existe.', 'Hebrews 11:6', 'Without faith it is impossible to please God, because anyone who comes to him must believe that he exists.', 'Hebreos 11:6', 'Sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay.'),
    ('Mateus 17:20', 'Se tiverdes fé como um grão de mostarda, direis a este monte: muda daqui para acolá, e ele há de mudar.', 'Matthew 17:20', 'If you have faith as small as a mustard seed, you can say to this mountain, Move from here to there, and it will move.', 'Mateo 17:20', 'Si tuvierais fe como un grano de mostaza, diréis a este monte: Pásate de aquí allá, y se pasará.'),
    ('Salmo 56:3', 'No dia em que eu temer, hei de confiar em ti.', 'Psalm 56:3', 'When I am afraid, I put my trust in you.', 'Salmo 56:3', 'En el día que temo, yo en ti confío.'),
    ('Romanos 10:17', 'A fé vem pelo ouvir, e o ouvir pela palavra de Deus.', 'Romans 10:17', 'Faith comes from hearing the message, and the message is heard through the word about Christ.', 'Romanos 10:17', 'La fe es por el oír, y el oír por la palabra de Dios.'),
    ('Salmo 112:7', 'Não temerá más notícias; o seu coração está firme, confiando no Senhor.', 'Psalm 112:7', 'They will have no fear of bad news; their hearts are steadfast, trusting in the Lord.', 'Salmo 112:7', 'No tendrá temor de malas noticias; su corazón está firme, confiado en el Señor.'),
    ('1 João 5:4', 'Esta é a vitória que vence o mundo: a nossa fé.', '1 John 5:4', 'This is the victory that has overcome the world, even our faith.', '1 Juan 5:4', 'Esta es la victoria que ha vencido al mundo, nuestra fe.'),
    ('Salmo 13:5', 'Mas eu confio na tua benignidade; o meu coração se alegrará na tua salvação.', 'Psalm 13:5', 'But I trust in your unfailing love; my heart rejoices in your salvation.', 'Salmo 13:5', 'Mas yo en tu misericordia he confiado; mi corazón se alegrará en tu salvación.'),
    ('Provérbios 3:26', 'Porque o Senhor será a tua confiança e guardará os teus pés de serem presos.', 'Proverbs 3:26', 'For the Lord will be at your side and will keep your foot from being snared.', 'Proverbios 3:26', 'Porque el Señor será tu confianza, y él preservará tu pie de ser preso.'),
    ('Salmo 125:1', 'Os que confiam no Senhor serão como o monte de Sião, que não se abala, mas permanece para sempre.', 'Psalm 125:1', 'Those who trust in the Lord are like Mount Zion, which cannot be shaken but endures forever.', 'Salmo 125:1', 'Los que confían en el Señor son como el monte de Sion, que no se mueve, sino que permanece para siempre.'),
    ('Mateus 9:29', 'Seja feito para vós conforme a vossa fé.', 'Matthew 9:29', 'According to your faith let it be done to you.', 'Mateo 9:29', 'Conforme a vuestra fe os sea hecho.'),
    ('Salmo 26:1', 'Julga-me, Senhor, pois tenho andado na minha sinceridade; confio no Senhor sem vacilar.', 'Psalm 26:1', 'Vindicate me, Lord, for I have led a blameless life; I have trusted in the Lord and have not faltered.', 'Salmo 26:1', 'Júzgame, oh Señor, porque yo en mi integridad he andado; he confiado asimismo en el Señor, sin titubear.'),
    ('2 Coríntios 5:7', 'Porque andamos por fé, e não por vista.', '2 Corinthians 5:7', 'For we live by faith, not by sight.', '2 Corintios 5:7', 'Porque por fe andamos, no por vista.'),
    ('Salmo 115:11', 'Vós que temeis ao Senhor, confiai no Senhor; ele é o vosso auxílio e o vosso escudo.', 'Psalm 115:11', 'You who fear him, trust in the Lord; he is their help and shield.', 'Salmo 115:11', 'Los que teméis al Señor, confiad en el Señor; él es vuestra ayuda y vuestro escudo.'),
    ('Isaías 12:2', 'Eis que Deus é a minha salvação; eu confiarei e não temerei.', 'Isaiah 12:2', 'Surely God is my salvation; I will trust and not be afraid.', 'Isaías 12:2', 'He aquí, Dios es mi salvación; confiaré y no temeré.'),
    ('Salmo 31:14', 'Mas eu confio em ti, ó Senhor; eu digo: Tu és o meu Deus.', 'Psalm 31:14', 'But I trust in you, Lord; I say, You are my God.', 'Salmo 31:14', 'Mas yo en ti confío, oh Señor; digo: Tú eres mi Dios.'),
    ('Filipenses 1:6', 'Aquele que começou a boa obra em vós há de completá-la até ao dia de Jesus Cristo.', 'Philippians 1:6', 'He who began a good work in you will carry it on to completion until the day of Christ Jesus.', 'Filipenses 1:6', 'El que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo.'),
    ('Salmo 20:7', 'Uns confiam em carros e outros em cavalos, mas nós faremos menção do nome do Senhor nosso Deus.', 'Psalm 20:7', 'Some trust in chariots and some in horses, but we trust in the name of the Lord our God.', 'Salmo 20:7', 'Estos confían en carros, y aquellos en caballos; mas nosotros del nombre del Señor nuestro Dios tendremos memoria.'),
    ('Hebreus 10:23', 'Retenhamos firmes a confissão da nossa esperança, porque fiel é o que prometeu.', 'Hebrews 10:23', 'Let us hold unswervingly to the hope we profess, for he who promised is faithful.', 'Hebreos 10:23', 'Mantengamos firme, sin fluctuar, la profesión de nuestra esperanza, porque fiel es el que prometió.'),
    ('Salmo 9:10', 'Os que conhecem o teu nome confiarão em ti, pois tu, Senhor, nunca desamparas os que te buscam.', 'Psalm 9:10', 'Those who know your name trust in you, for you, Lord, have never forsaken those who seek you.', 'Salmo 9:10', 'En ti confiarán los que conocen tu nombre, por cuanto tú, oh Señor, no desamparaste a los que te buscan.'),
    ('1 Pedro 1:8', 'Não o havendo visto, amais; no qual, não o vendo agora, crendo, vos alegrais com gozo inefável.', '1 Peter 1:8', 'Though you have not seen him, you love him; and even though you do not see him now, you believe in him and are filled with joy.', '1 Pedro 1:8', 'A quien amáis sin haberle visto, en quien creyendo, aunque ahora no lo veáis, os alegráis con gozo inefable.'),
    ('Salmo 62:8', 'Confiai nele, ó povo, em todos os tempos; derramai perante ele o vosso coração.', 'Psalm 62:8', 'Trust in him at all times, you people; pour out your hearts to him.', 'Salmo 62:8', 'Confiad en él en todo tiempo, oh pueblo; derramad delante de él vuestro corazón.'),
    ('Marcos 9:23', 'Se tu podes crer; tudo é possível ao que crê.', 'Mark 9:23', 'If you can? Everything is possible for one who believes.', 'Marcos 9:23', 'Si puedes creer, al que cree todo le es posible.'),
    ('Salmo 37:5', 'Entrega o teu caminho ao Senhor; confia nele, e ele tudo fará.', 'Psalm 37:5', 'Commit your way to the Lord; trust in him and he will do this.', 'Salmo 37:5', 'Encomienda al Señor tu camino, y confía en él; y él hará.'),
    ('João 20:29', 'Bem-aventurados os que não viram e creram.', 'John 20:29', 'Blessed are those who have not seen and yet have believed.', 'Juan 20:29', 'Bienaventurados los que no vieron, y creyeron.'),
    ('Salmo 18:30', 'O caminho de Deus é perfeito; a palavra do Senhor é provada; ele é um escudo para todos os que nele confiam.', 'Psalm 18:30', "As for God, his way is perfect; the Lord's word is flawless; he shields all who take refuge in him.", 'Salmo 18:30', 'En cuanto a Dios, perfecto es su camino; acrisolada es la palabra del Señor; escudo es a todos los que en él esperan.'),
    ('Provérbios 28:25', 'O orgulhoso excita contendas, mas o que confia no Senhor prosperará.', 'Proverbs 28:25', 'The greedy stir up conflict, but those who trust in the Lord will prosper.', 'Proverbios 28:25', 'El altivo de ánimo suscita contiendas; mas el que confía en el Señor prosperará.'),
    ('Salmo 44:6', 'Porque não confiarei no meu arco, nem a minha espada me salvará.', 'Psalm 44:6', 'I put no trust in my bow, my sword does not bring me victory.', 'Salmo 44:6', 'Porque no confiaré en mi arco, ni mi espada me salvará.'),
    ('1 Crônicas 28:20', 'Esforça-te e tem bom ânimo, e faze a obra; não temas, nem te espantes, porque o Senhor Deus está contigo.', '1 Chronicles 28:20', 'Be strong and courageous, and do the work. Do not be afraid or discouraged, for the Lord God is with you.', '1 Crónicas 28:20', 'Esfuérzate, pues, y haz la obra; no temas ni desmayes, porque el Señor Dios, mi Dios, estará contigo.'),
    ('Salmo 91:2', 'Direi do Senhor: Ele é o meu refúgio e a minha fortaleza, o meu Deus, em quem confio.', 'Psalm 91:2', 'I will say of the Lord, He is my refuge and my fortress, my God, in whom I trust.', 'Salmo 91:2', 'Diré yo del Señor: Esperanza mía, y castillo mío; mi Dios, en quien confiaré.'),
    ('Salmo 91:4', 'Ele te cobrirá com as suas penas, e debaixo das suas asas estarás seguro.', 'Psalm 91:4', 'He will cover you with his feathers, and under his wings you will find refuge.', 'Salmo 91:4', 'Con sus plumas te cubrirá, y debajo de sus alas estarás seguro.'),
    ('Salmo 32:7', 'Tu és o meu esconderijo; tu me guardas da angústia e me cinges de alegria de livramento.', 'Psalm 32:7', 'You are my hiding place; you will protect me from trouble and surround me with songs of deliverance.', 'Salmo 32:7', 'Tú eres mi refugio; me guardarás de la angustia, con cánticos de liberación me rodearás.'),
    ('Salmo 61:3', 'Porque tu tens sido um refúgio para mim e uma torre forte contra o inimigo.', 'Psalm 61:3', 'For you have been my refuge, a strong tower against the foe.', 'Salmo 61:3', 'Porque tú has sido mi refugio, y torre fuerte delante del enemigo.'),
    ('Provérbios 18:10', 'O nome do Senhor é uma torre forte; para ela corre o justo e está em segurança.', 'Proverbs 18:10', 'The name of the Lord is a fortified tower; the righteous run to it and are safe.', 'Proverbios 18:10', 'Torre fuerte es el nombre del Señor; a ella correrá el justo, y será levantado.'),
    ('Salmo 142:5', 'Clamei a ti, ó Senhor; disse: Tu és o meu refúgio.', 'Psalm 142:5', 'I cry to you, Lord; I say, You are my refuge.', 'Salmo 142:5', 'Clamé a ti, oh Señor; dije: Tú eres mi refugio.'),
    ('Salmo 121:7', 'O Senhor te guardará de todo mal; ele guardará a tua alma.', 'Psalm 121:7', 'The Lord will keep you from all harm; he will watch over your life.', 'Salmo 121:7', 'El Señor te guardará de todo mal; él guardará tu alma.'),
    ('Salmo 46:7', 'O Senhor dos Exércitos está conosco; o Deus de Jacó é o nosso refúgio.', 'Psalm 46:7', 'The Lord Almighty is with us; the God of Jacob is our fortress.', 'Salmo 46:7', 'El Señor de los ejércitos está con nosotros; nuestro refugio es el Dios de Jacob.'),
    ('Salmo 94:22', 'Mas o Senhor é a minha defesa, e o meu Deus é a rocha do meu refúgio.', 'Psalm 94:22', 'But the Lord has become my fortress, and my God the rock in whom I take refuge.', 'Salmo 94:22', 'Mas el Señor me ha sido por refugio, y mi Dios por roca de mi confianza.'),
    ('Salmo 59:9', 'Porque tu, ó Deus, és a minha defesa e o meu refúgio no dia da angústia.', 'Psalm 59:9', 'You are my fortress, my refuge in times of trouble.', 'Salmo 59:9', 'Porque tú, oh Dios, eres mi fortaleza, mi refugio en el día de la angustia.'),
    ('Salmo 121:8', 'O Senhor guardará a tua entrada e a tua saída, desde agora e para sempre.', 'Psalm 121:8', 'The Lord will watch over your coming and going both now and forevermore.', 'Salmo 121:8', 'El Señor guardará tu salida y tu entrada, desde ahora y para siempre.'),
    ('Salmo 62:6', 'Só ele é a minha rocha e a minha salvação; é a minha defesa; não serei abalado.', 'Psalm 62:6', 'Truly he is my rock and my salvation; he is my fortress, I will not be shaken.', 'Salmo 62:6', 'Sólo él es mi roca y mi salvación; es mi refugio, no resbalaré.'),
    ('Salmo 119:114', 'Tu és o meu refúgio e o meu escudo; espero na tua palavra.', 'Psalm 119:114', 'You are my refuge and my shield; I have put my hope in your word.', 'Salmo 119:114', 'Mi escondedero y mi escudo eres tú; en tu palabra he esperado.'),
    ('Salmo 91:10', 'Nenhum mal te sucederá, nem praga alguma chegará à tua tenda.', 'Psalm 91:10', 'No harm will overtake you, no disaster will come near your tent.', 'Salmo 91:10', 'No te sobrevendrá mal, ni plaga tocará tu morada.'),
    ('Salmo 18:2', 'O Senhor é a minha rocha, a minha fortaleza e o meu libertador; o meu Deus, a minha rocha, em quem me refugio.', 'Psalm 18:2', 'The Lord is my rock, my fortress and my deliverer; my God is my rock, in whom I take refuge.', 'Salmo 18:2', 'El Señor es mi roca, mi fortaleza y mi libertador; mi Dios, mi fortaleza, en quien me refugiaré.'),
    ('Salmo 46:1', 'Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia.', 'Psalm 46:1', 'God is our refuge and strength, an ever-present help in trouble.', 'Salmo 46:1', 'Dios es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.'),
    ('Salmo 71:3', 'Sê para mim uma rocha de refúgio, a que sempre possa recorrer.', 'Psalm 71:3', 'Be my rock of refuge, to which I can always go.', 'Salmo 71:3', 'Sé tú mi roca de refugio, a quien recurra yo siempre.'),
    ('Salmo 121:5', 'O Senhor é quem te guarda; o Senhor é a tua sombra à tua direita.', 'Psalm 121:5', 'The Lord watches over you; the Lord is your shade at your right hand.', 'Salmo 121:5', 'El Señor es tu guardador; el Señor es tu sombra a tu diestra.'),
    ('Salmo 27:5', 'Porque no dia da adversidade me esconderá no seu pavilhão.', 'Psalm 27:5', 'For in the day of trouble he will keep me safe in his dwelling.', 'Salmo 27:5', 'Porque él me esconderá en su tabernáculo en el día del mal.'),
    ('Salmo 59:16', 'Porque tu tens sido o meu alto refúgio e o meu abrigo no dia da angústia.', 'Psalm 59:16', 'For you have been my fortress, a refuge in times of trouble.', 'Salmo 59:16', 'Porque tú has sido mi refugio, y torre fuerte delante del enemigo.'),
    ('Salmo 144:2', 'Ele é a minha benignidade e a minha fortaleza; o meu alto refúgio e o meu libertador.', 'Psalm 144:2', 'He is my loving God and my fortress, my stronghold and my deliverer.', 'Salmo 144:2', 'Misericordia mía y mi fortaleza, mi baluarte y mi libertador.'),
    ('Salmo 5:11', 'Alegrem-se todos os que confiam em ti; exultem eternamente, porquanto tu os defendes.', 'Psalm 5:11', 'But let all who take refuge in you be glad; let them ever sing for joy.', 'Salmo 5:11', 'Alégrense todos los que en ti confían; den voces de júbilo para siempre.'),
    ('Salmo 3:3', 'Mas tu, Senhor, és um escudo ao redor de mim; a minha glória, e o que exalta a minha cabeça.', 'Psalm 3:3', 'But you, Lord, are a shield around me, my glory, the One who lifts my head high.', 'Salmo 3:3', 'Mas tú, Señor, eres escudo alrededor de mí; mi gloria, y el que levanta mi cabeza.'),
    ('Salmo 119:117', 'Sustenta-me, e serei salvo, e considerarei continuamente os teus estatutos.', 'Psalm 119:117', 'Uphold me, and I will be delivered; I will always have regard for your decrees.', 'Salmo 119:117', 'Sosténme, y seré salvo, y me regocijaré en tus estatutos.'),
    ('Salmo 36:7', 'Como é preciosa a tua benignidade, ó Deus! Os filhos dos homens se refugiam à sombra das tuas asas.', 'Psalm 36:7', 'How priceless is your unfailing love, O God! People take refuge in the shadow of your wings.', 'Salmo 36:7', '¡Cuán preciosa, oh Dios, es tu misericordia! Los hijos de los hombres se amparan bajo la sombra de tus alas.'),
    ('Salmo 31:20', 'Tu os esconderás, no secreto da tua presença, da conspiração dos homens.', 'Psalm 31:20', 'In the shelter of your presence you hide them from all human intrigues.', 'Salmo 31:20', 'Los esconderás en el secreto de tu presencia de la conspiración del hombre.'),
    ('Salmo 17:8', 'Guarda-me como à menina do teu olho; esconde-me à sombra das tuas asas.', 'Psalm 17:8', 'Keep me as the apple of your eye; hide me in the shadow of your wings.', 'Salmo 17:8', 'Guárdame como a la niña del ojo; escóndeme bajo la sombra de tus alas.'),
    ('Salmo 140:7', 'Ó Senhor Deus, força da minha salvação, tu cobriste a minha cabeça no dia da batalha.', 'Psalm 140:7', 'Sovereign Lord, my strong deliverer, you shield my head in the day of battle.', 'Salmo 140:7', 'Jehová el Señor, fortaleza de mi salvación, amparaste mi cabeza en el día de la batalla.'),
    ('Salmo 61:4', 'Habitarei no teu tabernáculo para sempre; estarei seguro no esconderijo das tuas asas.', 'Psalm 61:4', 'I long to dwell in your tent forever and take refuge in the shelter of your wings.', 'Salmo 61:4', 'Yo moraré en tu tabernáculo para siempre; estaré seguro bajo la cubierta de tus alas.'),
    ('Salmo 71:1', 'Em ti, Senhor, confio; nunca seja eu confundido.', 'Psalm 71:1', 'In you, Lord, I have taken refuge; let me never be put to shame.', 'Salmo 71:1', 'En ti, oh Señor, me he refugiado; no sea yo avergonzado jamás.'),
    ('Salmo 91:1', 'Aquele que habita no esconderijo do Altíssimo, à sombra do Onipotente descansará.', 'Psalm 91:1', 'Whoever dwells in the shelter of the Most High will rest in the shadow of the Almighty.', 'Salmo 91:1', 'El que habita al abrigo del Altísimo morará bajo la sombra del Omnipotente.'),
    ('1 Tessalonicenses 5:17', 'Orai sem cessar.', '1 Thessalonians 5:17', 'Pray continually.', '1 Tesalonicenses 5:17', 'Orad sin cesar.'),
    ('Filipenses 4:6', 'Em tudo, pela oração e súplica, com ações de graças, apresentai os vossos pedidos a Deus.', 'Philippians 4:6', 'In every situation, by prayer and petition, with thanksgiving, present your requests to God.', 'Filipenses 4:6', 'En todo, por oración y ruego, con acción de gracias, sean dadas a conocer vuestras peticiones a Dios.'),
    ('Mateus 6:6', 'Tu, quando orares, entra no teu aposento e, fechando a tua porta, ora a teu Pai em secreto.', 'Matthew 6:6', 'When you pray, go into your room, close the door and pray to your Father, who is unseen.', 'Mateo 6:6', 'Tú, cuando ores, entra en tu aposento, y cerrada la puerta, ora a tu Padre que está en secreto.'),
    ('Salmo 145:18', 'Perto está o Senhor de todos os que o invocam, de todos os que o invocam em verdade.', 'Psalm 145:18', 'The Lord is near to all who call on him, to all who call on him in truth.', 'Salmo 145:18', 'Cercano está el Señor a todos los que le invocan, a todos los que le invocan de veras.'),
    ('Jeremias 33:3', 'Clama a mim, e responder-te-ei, e anunciar-te-ei coisas grandes e firmes.', 'Jeremiah 33:3', 'Call to me and I will answer you and tell you great and unsearchable things you do not know.', 'Jeremías 33:3', 'Clama a mí, y yo te responderé, y te enseñaré cosas grandes y ocultas que tú no conoces.'),
    ('Salmo 66:19', 'Mas Deus ouviu-me; atendeu à voz da minha oração.', 'Psalm 66:19', 'But God has surely listened and has heard my prayer.', 'Salmo 66:19', 'Mas ciertamente me escuchó Dios; atendió a la voz de mi súplica.'),
    ('João 15:7', 'Se permanecerdes em mim, e as minhas palavras permanecerem em vós, pedireis o que quiserdes e vos será feito.', 'John 15:7', 'If you remain in me and my words remain in you, ask whatever you wish, and it will be done for you.', 'Juan 15:7', 'Si permanecéis en mí, y mis palabras permanecen en vosotros, pedid todo lo que queréis, y os será hecho.'),
    ('Salmo 55:17', 'À tarde, e à manhã, e ao meio-dia orarei; e clamarei, e ele ouvirá a minha voz.', 'Psalm 55:17', 'Evening, morning and noon I cry out in distress, and he hears my voice.', 'Salmo 55:17', 'Tarde y mañana y a mediodía oraré y clamaré, y él oirá mi voz.'),
    ('1 João 5:14', 'Esta é a confiança que temos nele: que, se pedirmos alguma coisa segundo a sua vontade, ele nos ouve.', '1 John 5:14', 'This is the confidence we have in approaching God: that if we ask anything according to his will, he hears us.', '1 Juan 5:14', 'Esta es la confianza que tenemos en él: que si pedimos alguna cosa conforme a su voluntad, él nos oye.'),
    ('Salmo 34:17', 'Os justos clamam, e o Senhor os ouve e os livra de todas as suas angústias.', 'Psalm 34:17', 'The righteous cry out, and the Lord hears them; he delivers them from all their troubles.', 'Salmo 34:17', 'Claman los justos, y el Señor oye, y los libra de todas sus angustias.'),
    ('Mateus 21:22', 'E tudo o que pedirdes na oração, crendo, o recebereis.', 'Matthew 21:22', 'If you believe, you will receive whatever you ask for in prayer.', 'Mateo 21:22', 'Y todo lo que pidiereis en oración, creyendo, lo recibiréis.'),
    ('Salmo 65:2', 'Ó tu que ouves a oração, a ti virá toda a carne.', 'Psalm 65:2', 'You who answer prayer, to you all people will come.', 'Salmo 65:2', 'Tú oyes la oración; a ti vendrá toda carne.'),
    ('Lucas 18:1', 'Deve-se sempre orar e nunca desanimar.', 'Luke 18:1', 'Always pray and not give up.', 'Lucas 18:1', 'Es necesario orar siempre, y no desmayar.'),
    ('Salmo 91:15', 'Ele me invocará, e eu lhe responderei; na angústia estarei com ele.', 'Psalm 91:15', 'He will call on me, and I will answer him; I will be with him in trouble.', 'Salmo 91:15', 'Me invocará, y yo le responderé; con él estaré yo en la angustia.'),
    ('Efésios 6:18', 'Orando em todo o tempo com toda a oração e súplica no Espírito.', 'Ephesians 6:18', 'And pray in the Spirit on all occasions with all kinds of prayers and requests.', 'Efesios 6:18', 'Orando en todo tiempo con toda oración y súplica en el Espíritu.'),
    ('Salmo 102:17', 'Ele atenderá à oração do desamparado e não desprezará a sua oração.', 'Psalm 102:17', 'He will respond to the prayer of the destitute; he will not despise their plea.', 'Salmo 102:17', 'Él oirá la oración del menesteroso, y no despreciará su ruego.'),
    ('Marcos 11:25', 'Quando estiverdes orando, perdoai, para que vosso Pai celestial vos perdoe.', 'Mark 11:25', 'When you stand praying, forgive, so that your Father in heaven may forgive you.', 'Marcos 11:25', 'Cuando estéis orando, perdonad, si tenéis algo contra alguno, para que también vuestro Padre os perdone.'),
    ('Salmo 5:3', 'Pela manhã ouvirás a minha voz, ó Senhor; pela manhã apresentarei a ti a minha oração.', 'Psalm 5:3', 'In the morning, Lord, you hear my voice; in the morning I lay my requests before you.', 'Salmo 5:3', 'Oh Señor, de mañana oirás mi voz; de mañana me presentaré delante de ti, y esperaré.'),
    ('1 Crônicas 16:11', 'Buscai ao Senhor e a sua força; buscai a sua face continuamente.', '1 Chronicles 16:11', 'Look to the Lord and his strength; seek his face always.', '1 Crónicas 16:11', 'Buscad al Señor y su poder; buscad su rostro continuamente.'),
    ('Salmo 17:6', 'Eu te invoquei, ó Deus, pois tu me ouvirás; inclina a mim os teus ouvidos.', 'Psalm 17:6', 'I call on you, my God, for you will answer me; turn your ear to me and hear my prayer.', 'Salmo 17:6', 'Yo te invoco, por cuanto tú me oirás, oh Dios; inclina a mí tu oído, escucha mi palabra.'),
    ('Salmos 119:58', 'De todo o meu coração te busquei; não me deixes desviar dos teus mandamentos.', 'Psalm 119:58', 'I have sought your face with all my heart; be gracious to me according to your promise.', 'Salmo 119:58', 'De todo mi corazón te he buscado; no me dejes desviarme de tus mandamientos.'),
    ('João 16:24', 'Pedi, e recebereis, para que o vosso gozo seja completo.', 'John 16:24', 'Ask and you will receive, and your joy will be complete.', 'Juan 16:24', 'Pedid, y recibiréis, para que vuestro gozo sea completo.'),
    ('Salmo 40:1', 'Esperei com paciência no Senhor, e ele se inclinou para mim e ouviu o meu clamor.', 'Psalm 40:1', 'I waited patiently for the Lord; he turned to me and heard my cry.', 'Salmo 40:1', 'Pacientemente esperé al Señor, y se inclinó a mí y oyó mi clamor.'),
    ('Salmo 141:2', 'Suba a minha oração como incenso perante a tua face.', 'Psalm 141:2', 'May my prayer be set before you like incense.', 'Salmo 141:2', 'Suba mi oración delante de ti como el incienso.'),
    ('Atos 2:42', 'E perseveravam na doutrina dos apóstolos, na comunhão, no partir do pão e nas orações.', 'Acts 2:42', "They devoted themselves to the apostles' teaching and to fellowship, to the breaking of bread and to prayer.", 'Hechos 2:42', 'Y perseveraban en la doctrina de los apóstoles, en la comunión, en el partimiento del pan y en las oraciones.'),
    ('Salmo 50:15', 'Invoca-me no dia da angústia; eu te livrarei, e tu me glorificarás.', 'Psalm 50:15', 'Call on me in the day of trouble; I will deliver you, and you will honor me.', 'Salmo 50:15', 'Invócame en el día de la angustia; te libraré, y tú me honrarás.'),
    ('Mateus 7:11', 'Se vós, sendo maus, sabeis dar boas dádivas aos vossos filhos, quanto mais vosso Pai celestial?', 'Matthew 7:11', 'If you, then, though you are evil, know how to give good gifts to your children, how much more will your Father in heaven give good gifts?', 'Mateo 7:11', 'Si vosotros, siendo malos, sabéis dar buenas dádivas a vuestros hijos, ¿cuánto más vuestro Padre celestial?'),
    ('Salmo 66:20', 'Bendito seja Deus, que não rejeitou a minha oração, nem desviou de mim a sua benignidade.', 'Psalm 66:20', 'Praise be to God, who has not rejected my prayer or withheld his love from me!', 'Salmo 66:20', 'Bendito sea Dios, que no echó de mí mi oración, ni de mí su misericordia.'),
    ('Lucas 11:9', 'Pedi, e dar-se-vos-á; buscai, e encontrareis; batei, e abrir-se-vos-á.', 'Luke 11:9', 'Ask and it will be given to you; seek and you will find; knock and the door will be opened to you.', 'Lucas 11:9', 'Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá.'),
    ('Salmo 69:13', 'Mas eu, Senhor, faço a minha oração a ti por tempo favorável, na grandeza da tua benignidade.', 'Psalm 69:13', 'But I pray to you, Lord, in the time of your favor; in your great love answer me.', 'Salmo 69:13', 'Pero yo a ti oraba, oh Señor, al tiempo de tu buena voluntad.'),
    ('Isaías 43:19', 'Eis que faço uma coisa nova; agora sairá à luz; abrirei caminho no deserto e rios no ermo.', 'Isaiah 43:19', 'See, I am doing a new thing! Now it springs up; I am making a way in the wilderness and streams in the wasteland.', 'Isaías 43:19', 'He aquí que yo hago cosa nueva; pronto saldrá a luz; abriré camino en el desierto, y ríos en la soledad.'),
    ('2 Coríntios 5:17', 'Se alguém está em Cristo, é nova criatura; as coisas velhas já passaram, eis que tudo se fez novo.', '2 Corinthians 5:17', 'If anyone is in Christ, the new creation has come: the old has gone, the new is here!', '2 Corintios 5:17', 'Si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.'),
    ('Salmo 126:3', 'O Senhor fez grandes coisas por nós; por isso, estamos alegres.', 'Psalm 126:3', 'The Lord has done great things for us, and we are filled with joy.', 'Salmo 126:3', 'Grandes cosas ha hecho el Señor con nosotros; estamos alegres.'),
    ('Lamentações 3:22', 'As misericórdias do Senhor são a causa de não sermos consumidos.', 'Lamentations 3:22', "Because of the Lord's great love we are not consumed, for his compassions never fail.", 'Lamentaciones 3:22', 'Por la misericordia del Señor no hemos sido consumidos, porque nunca decayeron sus misericordias.'),
    ('Salmo 30:5', 'O choro pode durar uma noite, mas a alegria vem pela manhã.', 'Psalm 30:5', 'Weeping may stay for the night, but rejoicing comes in the morning.', 'Salmo 30:5', 'Por la noche durará el llanto, y a la mañana vendrá la alegría.'),
    ('Miqueias 7:7', 'Eu, porém, olharei para o Senhor; esperarei no Deus da minha salvação.', 'Micah 7:7', 'But as for me, I watch in hope for the Lord, I wait for God my Savior.', 'Miqueas 7:7', 'Mas yo a Jehová miraré, esperaré al Dios de mi salvación.'),
    ('Salmo 42:11', 'Por que estás abatida, ó minha alma? Espera em Deus, pois ainda o louvarei.', 'Psalm 42:11', 'Why, my soul, are you downcast? Put your hope in God, for I will yet praise him.', 'Salmo 42:11', '¿Por qué te abates, oh alma mía, y por qué te turbas dentro de mí? Espera en Dios, porque aún he de alabarle.'),
    ('Romanos 15:13', 'O Deus de esperança vos encha de todo o gozo e paz em crença, para que abundeis em esperança.', 'Romans 15:13', 'May the God of hope fill you with all joy and peace as you trust in him, so that you may overflow with hope.', 'Romanos 15:13', 'El Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza.'),
    ('Salmo 62:5', 'Ó minha alma, espera somente em Deus, porque dele vem a minha esperança.', 'Psalm 62:5', 'Yes, my soul, find rest in God; my hope comes from him.', 'Salmo 62:5', 'Alma mía, en Dios solamente reposa, porque de él es mi esperanza.'),
    ('Isaías 40:31', 'Os que esperam no Senhor renovarão as suas forças; subirão com asas como águias.', 'Isaiah 40:31', 'Those who hope in the Lord will renew their strength; they will soar on wings like eagles.', 'Isaías 40:31', 'Los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas.'),
    ('Salmo 33:22', 'Seja a tua benignidade, Senhor, sobre nós, como em ti esperamos.', 'Psalm 33:22', 'May your unfailing love be with us, Lord, even as we put our hope in you.', 'Salmo 33:22', 'Sea tu misericordia, oh Señor, sobre nosotros, según esperamos en ti.'),
    ('Hebreus 6:19', 'Temos esta esperança como âncora da alma, segura e firme.', 'Hebrews 6:19', 'We have this hope as an anchor for the soul, firm and secure.', 'Hebreos 6:19', 'La cual tenemos como segura y firme ancla del alma.'),
    ('Salmo 146:5', 'Bem-aventurado aquele cujo auxílio é o Deus de Jacó, e cuja esperança está no Senhor seu Deus.', 'Psalm 146:5', 'Blessed are those whose help is the God of Jacob, whose hope is in the Lord their God.', 'Salmo 146:5', 'Bienaventurado aquel cuyo auxilio es el Dios de Jacob, cuya esperanza está en el Señor su Dios.'),
    ('Isaías 49:13', 'Regozijai-vos, ó céus, e alegra-te, ó terra; porque o Senhor consolará o seu povo.', 'Isaiah 49:13', 'Shout for joy, you heavens; rejoice, you earth; for the Lord comforts his people.', 'Isaías 49:13', 'Cantad alabanzas, oh cielos, y alégrate, oh tierra; porque el Señor consolará a su pueblo.'),
    ('Salmo 71:5', 'Porque tu és a minha esperança, Senhor Deus; tu és a minha confiança desde a minha mocidade.', 'Psalm 71:5', 'For you have been my hope, Sovereign Lord, my confidence since my youth.', 'Salmo 71:5', 'Porque tú, oh Señor Dios, eres mi esperanza, mi confianza desde mi juventud.'),
    ('Salmo 130:7', 'Espere Israel no Senhor, pois no Senhor há misericórdia e abundante redenção.', 'Psalm 130:7', 'Israel, put your hope in the Lord, for with the Lord is unfailing love and with him is full redemption.', 'Salmo 130:7', 'Espere Israel al Señor, porque en el Señor hay misericordia, y abundante redención con él.'),
    ('Isaías 61:3', 'Para dar-lhes coroa em vez de cinzas, óleo de alegria em vez de pranto.', 'Isaiah 61:3', 'To bestow on them a crown of beauty instead of ashes, the oil of joy instead of mourning.', 'Isaías 61:3', 'Para darles gloria en lugar de ceniza, óleo de gozo en lugar de luto.'),
    ('Salmo 16:11', 'Na tua presença há plenitude de alegria; à tua mão direita há delícias perpetuamente.', 'Psalm 16:11', 'In your presence there is fullness of joy; at your right hand are eternal pleasures.', 'Salmo 16:11', 'En tu presencia hay plenitud de gozo; delicias a tu diestra para siempre.'),
    ('Sofonias 3:17', 'O Senhor teu Deus está no meio de ti, poderoso para salvar; ele se deleitará em ti com alegria.', 'Zephaniah 3:17', 'The Lord your God is with you, the Mighty Warrior who saves. He will rejoice over you with gladness.', 'Sofonías 3:17', 'El Señor tu Dios está en medio de ti, poderoso, él salvará; se gozará sobre ti con alegría.'),
    ('Salmo 118:14', 'O Senhor é a minha força e o meu cântico; e se tornou a minha salvação.', 'Psalm 118:14', 'The Lord is my strength and my defense; he has become my salvation.', 'Salmo 118:14', 'El Señor es mi fortaleza y mi cántico, y ha sido mi salvación.'),
    ('Isaías 35:10', 'Os resgatados do Senhor voltarão e virão a Sião com júbilo; e alegria eterna haverá sobre a sua cabeça.', 'Isaiah 35:10', 'Those the Lord has rescued will return. They will enter Zion with singing; everlasting joy will crown their heads.', 'Isaías 35:10', 'Los rescatados por el Señor volverán y vendrán a Sion con cánticos, y gozo perpetuo será sobre sus cabezas.'),
    ('Salmo 27:13', 'Cri que veria a bondade do Senhor na terra dos viventes.', 'Psalm 27:13', 'I remain confident of this: I will see the goodness of the Lord in the land of the living.', 'Salmo 27:13', 'Hubiera yo desmayado, si no creyera que veré la bondad del Señor en la tierra de los vivientes.'),
    ('Joel 2:25', 'Restituir-vos-ei os anos que comeu o gafanhoto.', 'Joel 2:25', 'I will repay you for the years the locusts have eaten.', 'Joel 2:25', 'Os restituiré los años que comió la oruga.'),
    ('Salmo 115:13', 'Ele abençoará os que temem ao Senhor, tanto pequenos como grandes.', 'Psalm 115:13', 'He will bless those who fear the Lord, small and great alike.', 'Salmo 115:13', 'Bendecirá a los que temen al Señor, tanto a los pequeños como a los grandes.'),
    ('Isaías 54:10', 'Porque os montes se retirarão, e os outeiros serão abalados; mas a minha benignidade não se apartará de ti.', 'Isaiah 54:10', 'Though the mountains be shaken and the hills be removed, yet my unfailing love for you will not be shaken.', 'Isaías 54:10', 'Porque los montes se moverán, y los collados temblarán, pero no se apartará de ti mi misericordia.'),
    ('Salmo 126:5', 'Os que semeiam em lágrimas segarão com alegria.', 'Psalm 126:5', 'Those who sow with tears will reap with songs of joy.', 'Salmo 126:5', 'Los que sembraron con lágrimas, con regocijo segarán.'),
    ('Eclesiastes 3:11', 'Tudo fez Deus formoso no seu devido tempo.', 'Ecclesiastes 3:11', 'He has made everything beautiful in its time.', 'Eclesiastés 3:11', 'Él hizo todo hermoso en su tiempo.'),
    ('Salmo 128:2', 'Pois comerás do trabalho das tuas mãos; feliz serás, e te irá bem.', 'Psalm 128:2', 'You will eat the fruit of your labor; blessings and prosperity will be yours.', 'Salmo 128:2', 'Cuando comieres el trabajo de tus manos, bienaventurado serás, y te irá bien.'),
    ('Isaías 58:11', 'O Senhor te guiará continuamente, e fartará a tua alma em lugares áridos.', 'Isaiah 58:11', 'The Lord will guide you always; he will satisfy your needs in a sun-scorched land.', 'Isaías 58:11', 'El Señor te pastoreará siempre, y en las sequías saciará tu alma.'),
    ('Salmo 138:8', 'O Senhor aperfeiçoará o que me concerne; a tua benignidade, ó Senhor, dura para sempre.', 'Psalm 138:8', 'The Lord will vindicate me; your love, Lord, endures forever.', 'Salmo 138:8', 'El Señor cumplirá su propósito en mí; tu misericordia, oh Señor, es para siempre.'),
]


def obter_versiculo(dia_do_ano, idioma="pt"):
    """Retorna {"referencia": ..., "texto": ...} para o dia do ano (1..365)."""
    idx = (dia_do_ano - 1) % len(_VERSE_TABLE)
    pref_pt, txt_pt, pref_en, txt_en, pref_es, txt_es = _VERSE_TABLE[idx]
    if idioma == "en":
        return {"referencia": pref_en, "texto": txt_en}
    if idioma == "es":
        return {"referencia": pref_es, "texto": txt_es}
    return {"referencia": pref_pt, "texto": txt_pt}
